window.DATA = window.DATA || {}; (window.DATA.problemsAdd = window.DATA.problemsAdd || []).push({

 /* ===================== 중3 (kor-g3.js) ===================== */
 "kor-g3-lit-interp": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"어떤 시의 1~5연이 모두 밝고 따뜻한 봄의 이미지로 이루어져 있는데, 한 학생이 4연의 '그늘' 한 단어만을 근거로 '이 시는 절망을 노래한다'고 해석했다. 이 해석에 대한 평가로 가장 적절한 것은?", opts:["작품 구절을 근거로 들었으므로 타당한 해석이다.","작품 전체의 흐름과 어긋나므로 일관성이 부족하다.","작가의 생애를 근거로 삼지 않아 타당하지 않다.","독자의 경험이 담기지 않아 해석이 아니라 감상이다."], a:1, exp:"근거가 한 단어뿐이고(충분성 부족) 시 전체의 밝은 흐름과 모순되므로 일관성이 없다. 구절을 들었다고 곧 타당한 것은 아니며, 작가 정보는 필수 조건이 아니다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 중 **독자**의 경험·가치관을 근거로 삼은 해석은?", opts:["'문이 닫힌다'가 세 번 반복되어 단절감이 강조된다.","이 시는 시인이 고향을 떠난 해에 쓰였으므로 향수를 담았다.","전학을 여러 번 다닌 내 경험에 비추어 '닫힌 문'은 새 환경에 대한 두려움으로 읽힌다.","산업화로 농촌이 비어 가던 시대상이 '빈집'에 반영되었다."], a:2, exp:"③은 읽는 사람의 경험을 근거로 삼은 독자 근거. ①은 작품 자체(내적 근거), ②는 작가, ④는 시대·현실(외적 근거).", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 시>\n낡은 운동화 한 켤레 현관에 놓여 있다\n끈은 풀린 채, 흙은 마른 채\n아무도 신지 않는데\n어머니는 매일 그 자리를 닦는다\n\n<두 해석>\n(가) '아무도 신지 않는데'와 '매일 닦는다'가 맞서 놓여, 떠난 사람을 기다리는 마음이 드러난다.\n(나) 이 시는 시인이 형을 멀리 떠나보낸 뒤 쓴 것이므로 형에 대한 그리움을 담았다.", q:"두 해석에 대한 설명으로 옳은 것만 고른 것은?\nㄱ. (가)는 시어의 대비라는 작품 내적 근거에 기댔다.\nㄴ. (나)는 작가의 생애라는 외적 근거에 기댔다.\nㄷ. (나)는 작가 정보를 썼으므로 (가)보다 언제나 타당하다.\nㄹ. 3·4행의 대비는 (가)와 (나) 모두의 근거가 될 수 있다.", opts:["ㄱ, ㄴ","ㄱ, ㄷ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ"], a:2, exp:"(가)는 작품 자체, (나)는 작가 근거(ㄱ·ㄴ). 작가 정보도 네 근거 중 하나일 뿐 우열이 정해져 있지 않으므로 ㄷ은 틀림. 3·4행의 대비는 두 해석 모두를 뒷받침할 수 있다(ㄹ).", why3:"'언제나·반드시' 같은 단정이 든 선지는 근거 유형 사이의 우열을 전제하므로 먼저 의심한다.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"위 <자작 시>(낡은 운동화)에 대한 해석 (가)와 (나) 중 하나를 택하고, 시의 구절을 두 군데 이상 인용하여 그 해석을 뒷받침하시오. 또 자신이 택한 해석이 더 타당하다고 본 기준을 한 문장으로 쓰시오.", model:"(가)를 택한다. '아무도 신지 않는데'는 운동화 주인의 부재를, '매일 그 자리를 닦는다'는 그 부재를 받아들이지 못하는 기다림을 보여 준다. 또 '끈은 풀린 채, 흙은 마른 채'는 주인이 떠난 뒤 시간이 흘렀음을 드러내 기다림의 길이를 강조한다. (가)는 작품 안의 구절만으로 설명되어 근거의 적절성이 높으므로 더 타당하다.", rubric:[["입장 선택 명시",1],["구절 인용 ① + 의미 연결",3],["구절 인용 ② + 의미 연결",3],["타당성 판단 기준(적절성·충분성·일관성) 제시",2],["문장 완결",1]], exp:"구절을 따옴표로 그대로 인용하고 '그래서 어떤 의미인가'를 붙여야 근거 항목 만점. 느낌만 쓰면 감상으로 보아 감점." }
 ],

 "kor-g3-lit-classic": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 중 **해학**이 두드러진 장면은?", opts:["글도 못 읽는 양반이 책을 거꾸로 들고 호통치는 모습을 그린다.","가난한 농부가 콩 한 알을 잃고 온 마을을 뒤지다가 제 주머니에서 찾고 머쓱하게 웃는다.","탐관오리가 백성의 쌀을 빼앗아 창고에 쌓는 모습을 고발한다.","억울하게 옥에 갇힌 주인공이 하늘을 향해 통곡한다."], a:1, exp:"약자(가난한 농부)의 허술함을 정겹게 웃기며 감싸므로 해학. ①·③은 권력자를 비꼬아 비판하는 풍자, ④는 비극적 장면.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"고전 시가·고전 소설에 대한 설명으로 옳은 것은?", opts:["가사는 3장 6구의 짧은 정형시이다.","고전 소설에서 서술자가 '슬프다, 이 일을 어찌하랴' 하고 끼어드는 것은 편집자적 논평이다.","시조의 종장 첫 구는 반드시 4음절이어야 한다.","고전 소설은 사건을 시간 순서와 무관하게 배열하는 것이 일반적이다."], a:1, exp:"서술자가 사건 밖에서 직접 평하는 것이 편집자적 논평. ①은 시조의 특징(가사는 4음보 연속체), ③종장 첫 구는 3음절, ④고전 소설은 대체로 시간 순서 구성.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 고전풍 노래>\n곳간 열쇠 허리에 차고 글 한 줄 못 읽는 양반님\n종더러 상소를 쓰라 호통치니 그 호령 천둥 같네\n뒷간에 앉아서도 갓끈을 고쳐 매니 그 체면 참으로 가상하다\n\n<보기> 조선 후기에는 돈으로 양반 신분을 사는 일이 늘어 글을 모르는 양반이 생겼고, 신분 질서가 흔들렸다.", q:"<보기>를 참고하여 윗글을 감상한 내용으로 가장 적절한 것은?", opts:["종에게 상소를 쓰게 하는 장면은 양반의 무능을 드러내어 비판하므로 풍자에 해당한다.","화자는 양반의 딱한 처지를 연민하며 감싸는 해학적 태도를 보인다.","마지막 행의 '가상하다'는 양반의 체면 의식을 진심으로 칭찬한 말이다.","신분 질서가 굳건하던 시기의 안정된 사회 모습이 반영되어 있다."], a:0, exp:"비꼼의 대상이 권위 있는 양반이므로 풍자(①). ②양반은 약자가 아니므로 해학이 아님. ③'가상하다'는 속뜻이 반대인 반어. ④<보기>는 신분 질서의 동요를 말한다.", why3:"웃음이 '위'를 찌르면 풍자, '아래'를 감싸면 해학 — 대상의 지위부터 확인.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"위 <자작 고전풍 노래>에서 풍자의 대상과 비판 내용을 쓰고, <보기>의 사회 상황과 연결하여 이 노래가 당대에 지닌 의미를 서술하시오. 또 오늘날의 관점에서 이 노래를 읽는 의미를 한 문장 덧붙이시오.", model:"풍자의 대상은 글도 못 읽으면서 체면만 차리는 양반이며, 실력 없이 신분과 권위만 내세우는 허위를 비판한다. <보기>처럼 돈으로 신분을 산 양반이 늘어 신분 질서가 흔들리던 시기에, 이 노래는 신분이 곧 능력이 아님을 드러내어 서민의 불만을 웃음으로 표출한 것이다. 오늘날에도 자리나 직함만으로 권위를 내세우는 태도를 돌아보게 한다.", rubric:[["풍자 대상 지목",2],["비판 내용(허위·무능)",2],["당대 사회 상황과 연결",3],["오늘날 관점의 의미",2],["문장 완결",1]], exp:"'가부장적이다·불공평하다'처럼 현대 관점만 쓰면 당대 맥락 항목 0점. 구절(글 못 읽음·호통·갓끈)을 근거로 대상을 짚어야 한다." }
 ],

 "kor-g3-gram-sentence": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"안긴문장의 종류가 바르게 짝지어진 것은?", opts:["나는 그가 떠났음을 몰랐다. — 관형절","동생은 발이 참 작다. — 서술절","비가 오면 소풍은 취소된다. — 부사절","누나가 \"먼저 가\"라고 말했다. — 명사절"], a:1, exp:"'발이 작다'가 주어 '동생은'을 서술하므로 서술절. ①'-음'은 명사절, ③'-면'은 종속적으로 이어진문장(안긴문장 아님), ④따옴표+'라고'는 인용절.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"'눈이 많이 왔다.'와 '길이 미끄럽다.'를 겹문장으로 바꾼 것에 대한 설명으로 옳은 것은?", opts:["'눈이 많이 와서 길이 미끄럽다.'는 두 사건의 원인·결과 관계가 드러난다.","'눈이 많이 오고 길이 미끄럽다.'는 앞뒤 절을 바꾸면 뜻이 달라지는 종속적 연결이다.","겹문장으로 바꾸면 항상 간결해지고 속도감이 생긴다.","'눈이 많이 와서 길이 미끄럽다.'는 서술어가 하나뿐인 홑문장이다."], a:0, exp:"'-아서'는 원인·결과의 논리 관계를 드러내는 종속적 연결. ②'-고'는 대등 연결, ③간결·속도감은 홑문장의 효과, ④서술어 '와서·미끄럽다' 둘이므로 겹문장.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<보기> 안긴문장은 문장 속에서 하는 역할에 따라 명사절·관형절·부사절·서술절·인용절로 나뉘며, 안긴문장 안에서는 앞뒤 문맥으로 알 수 있는 성분이 생략되기도 한다.\n\n㉠ 나는 그가 돌아오기를 바랐다.\n㉡ 우리는 밤이 깊도록 이야기했다.\n㉢ 할머니는 손이 참 크시다.\n㉣ 이 책은 내가 어제 산 것이다.", q:"<보기>를 바탕으로 ㉠~㉣을 탐구한 내용으로 옳은 것만 고른 것은?\nㄱ. ㉠의 안긴문장은 목적어 역할을 하는 명사절이다.\nㄴ. ㉡의 '밤이 깊도록'은 서술어를 꾸미는 부사절이다.\nㄷ. ㉢은 주어가 둘이므로 이어진문장이다.\nㄹ. ㉣의 관형절에는 목적어 '책을'이 생략되어 있다.", opts:["ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ"], a:2, exp:"㉠'-기'+'를'→목적어 명사절, ㉡'-도록'→부사절, ㉣'내가 (책을) 어제 샀다'에서 목적어 생략. ㉢은 '손이 크시다'가 서술절인 안은문장이지 이어진문장이 아니다.", why3:"'무엇이 무엇이 어떠하다' 꼴은 서술절부터 의심 — 주어가 둘이라고 이어진문장이 아니다.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"'형은 내가 만든 음식을 맛있게 먹었다.'에서 안긴문장을 그대로 찾아 쓰고 그 종류를 밝히시오. 안긴문장에서 생략된 성분을 복원하고, 이 문장을 두 홑문장으로 나누었을 때와 비교해 겹문장으로 쓸 때의 표현 효과를 서술하시오.", model:"안긴문장은 '내가 만든'이며 체언 '음식'을 꾸미는 관형절이다. 원래 문장 '내가 (음식을) 만들었다'에서 목적어 '음식을'이 생략되었다. '내가 음식을 만들었다. 형은 그 음식을 맛있게 먹었다.'로 나누면 간결하지만, 겹문장으로 쓰면 두 사건이 한 문장에 긴밀하게 묶여 '음식'이 누가 만든 것인지가 한눈에 드러난다.", rubric:[["안긴문장 '내가 만든' 정확히 인용",2],["종류: 관형절",2],["생략 성분: 목적어 '음식을' 복원",3],["겹문장의 효과(긴밀·정보 결합) 서술",2],["문장 완결",1]], exp:"안긴문장을 '내가 만든 음식을'처럼 체언까지 넣어 쓰면 감점. 효과는 홑문장(간결)과 대비해 써야 만점." }
 ],

 "kor-g3-gram-passive": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"밑줄 친 말이 **피동** 표현인 것은?", opts:["엄마가 아기에게 새 옷을 **입혔다**.","아기가 엄마 품에 포근히 **안겼다**.","형이 동생에게 책을 **읽혔다**.","선생님이 학생들을 운동장에 **모았다**."], a:1, exp:"'안기다'는 주어(아기)가 안는 행위를 당하므로 피동. ①③은 목적어가 있고 남에게 시키므로 사동, ④는 능동. 같은 접미사도 문장 안에서 '당하는가, 시키는가'로 가른다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"수진이 \"너 내일 여기서 몇 시에 만날래?\"라고 물은 것을 간접 인용으로 바르게 바꾼 것은?", opts:["수진은 나에게 내일 여기서 몇 시에 만날래라고 물었다.","수진은 나에게 다음 날 거기서 몇 시에 만나겠냐고 물었다.","수진은 나에게 다음 날 거기서 몇 시에 만나자고 물었다.","수진은 \"다음 날 거기서 몇 시에 만날래?\"고 물었다."], a:1, exp:"따옴표를 없애고 지시어(여기→거기)·시간 표현을 조정하며 의문문이므로 '-냐고'로 바꾼 ②. ①어미 미전환, ③청유 '-자고'는 뜻이 달라짐, ④따옴표를 남김.", err:"실수" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 기사 두 편>\n(가) 시청이 공원 나무 50그루를 베어 냈다. 시청 관계자는 \"안전을 위한 조치였다\"라고 말했다.\n(나) 공원 나무 50그루가 베어졌다. 관계자는 안전을 위한 조치였다고 말했다.", q:"두 기사의 표현에 대한 설명으로 옳은 것만 고른 것은?\nㄱ. (나)는 피동 표현을 써서 행위의 주체인 시청이 드러나지 않는다.\nㄴ. (가)의 인용은 원문을 그대로 옮긴 직접 인용으로 생생함과 신뢰를 준다.\nㄷ. (나)의 '베어졌다'는 피동 표지가 둘 겹친 이중 피동이다.\nㄹ. (나)의 인용은 따옴표 없이 '-고'를 붙인 간접 인용이다.", opts:["ㄱ, ㄴ","ㄷ, ㄹ","ㄱ, ㄴ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"], a:2, exp:"(나)는 행위자가 빠진 피동(ㄱ), (가)는 큰따옴표+'라고'의 직접 인용(ㄴ), (나)는 '-고'의 간접 인용(ㄹ). '베어지다'는 접미사 피동 없이 '-어지다'만 붙었으므로 이중 피동이 아니다(ㄷ 틀림).", why3:"'-어지다'를 보면 그 앞에 -이·히·리·기-가 이미 있는지부터 확인한다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"학급 신문의 문장 '교실 뒷문이 부서졌다.'를 능동문으로 바꾸어 쓰고(행위자는 '누군가'로 가정), 원래 피동문을 쓴 의도로 볼 수 있는 효과를 두 가지 서술하시오. 또 '부서졌다'가 이중 피동이 아닌 이유를 쓰시오.", model:"능동문: 누군가가 교실 뒷문을 부수었다. 피동문을 쓰면 첫째, 행위자를 드러내지 않아 책임의 소재가 흐려지고, 둘째, 당한 대상인 '뒷문'이 주어가 되어 사건 자체가 강조되며 객관적인 느낌을 준다. '부서지다'는 '부수다'에 접미사 피동이 없이 '-어지다'만 붙은 것이므로 피동 표지가 하나뿐이라 이중 피동이 아니다.", rubric:[["능동문 전환 정확",2],["효과 ① 행위자 숨김·책임 흐림",2],["효과 ② 대상 강조·객관적 느낌",2],["이중 피동 아닌 이유(표지 하나)",3],["문장 완결",1]], exp:"'부셔졌다'로 쓰면 맞춤법 감점. 이중 피동 판단은 '접미사 피동이 먼저 있는가'로 설명해야 만점." }
 ],

 "kor-g3-gram-spelling": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 중 '형태를 밝혀 어법에 맞도록' 적은 것이 **아니라** '소리대로' 적은 것은?", opts:["꽃을[꼬츨]","값도[갑또]","며칠[며칠]","먹어[머거]"], a:2, exp:"'며칠'은 '몇+일'로 원형을 밝혀도 뜻이 보이지 않아 소리대로 적는다. 나머지는 발음과 다르게 '꽃·값·먹-'의 형태를 고정해 어법에 맞게 적은 예.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"맞춤법과 띄어쓰기가 **모두** 바른 문장은?", opts:["그 일은 네가 할 수 밖에 없다.","왠일로 이렇게 일찍 왔니?","조용이 앉아서 기다려야 돼.","이번에는 틀림없이 될 거야."], a:3, exp:"④'될 거야'(의존 명사 '거' 띄어 씀)가 바르다. ①의존 명사 '수'+조사 '밖에'는 '수밖에'로 붙임, ②'웬일', ③'조용히'.", err:"실수" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자료> 표기와 발음\n| 표기 | 발음 | 원리 |\n|---|---|---|\n| ㉠ 꽃을 | [꼬츨] | ? |\n| ㉡ 며칠 | [며칠] | ? |\n| ㉢ 무릎이 | [무르피] | ? |\n| ㉣ 이튿날 | [이튼날] | ? |\n\n<보기> 한글 맞춤법 총칙 제1항: 표준어를 소리대로 적되, 어법에 맞도록 함을 원칙으로 한다.", q:"<보기>를 바탕으로 자료를 탐구한 내용으로 옳은 것은?", opts:["㉠과 ㉢은 체언의 형태를 고정해 적은 것으로 '어법에 맞도록'의 원리가 적용되었다.","㉡은 '몇'과 '일'의 원형을 밝혀 '몇일'로 적어야 총칙에 맞는다.","㉣은 '이틀'과 '날'의 형태를 밝혀 적은 것이다.","표기와 발음이 같은 ㉡은 맞춤법 원리와 관계가 없다."], a:0, exp:"'꽃·무릎'의 형태를 고정해 적어 뜻을 쉽게 알아보게 한 것이 어법에 맞도록 적기. ㉡은 원형을 밝혀도 뜻이 안 보여 소리대로 적는 예이므로 '몇일'은 틀림. ㉣은 '이틀'의 ㄹ이 아닌 ㄷ으로 적은 소리대로의 예. 소리대로 적기도 총칙의 원리이다.", why3:"표기≠발음이면 '어법', 표기=발음이면 '소리대로' — 둘 다 원칙이지 어느 쪽도 '틀린 것'이 아니다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"'밭을'은 [바틀]로 소리 나지만 '바틀'로 적지 않고 '밭을'로 적는다. 그 까닭을 한글 맞춤법 총칙 제1항의 내용을 들어 설명하고, 이렇게 적을 때의 좋은 점을 서술하시오.", model:"총칙 제1항은 '소리대로 적되 어법에 맞도록' 적는다고 규정한다. '밭을'은 체언 '밭'과 조사 '을'의 형태를 밝혀 적은 것으로, 소리대로 적는 대신 어법에 맞도록 적은 예이다. 이렇게 하면 '밭이·밭도·밭만'처럼 조사가 바뀌어도 '밭'의 형태가 일정하게 유지되어 읽는 사람이 뜻을 빠르고 정확하게 파악할 수 있다.", rubric:[["총칙 1항 내용(소리대로+어법에 맞도록) 제시",3],["'어법에 맞도록'=형태를 밝혀 적기로 설명",3],["좋은 점(뜻 파악 용이·형태 일정)",3],["문장 완결",1]], exp:"'어법에 맞도록'을 '문법에 맞는 문장'으로 쓰면 해당 항목 0점. '형태(원형)를 밝혀 적는다'는 표현이 들어가야 한다." }
 ],

 "kor-g3-gram-vocab": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"어휘의 갈래에 대한 설명으로 옳은 것은?", opts:["'학교·친구'는 중국에서 들어온 말이므로 외래어이다.","'피아노·버스'처럼 들어와 국어로 굳어진 말은 외래어로 국어 어휘에 속한다.","'하늘·마음'은 고유어이므로 공적 상황에서 쓰면 안 된다.","'리스크·스케줄'은 외래어이므로 바꿔 쓸 필요가 없다."], a:1, exp:"외래어는 국어 어휘의 한 갈래. ①한자어는 외래어와 별도 갈래, ③고유어 사용에 제한은 없음, ④'위험·일정'으로 바꿀 수 있는 말은 외국어 남용.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"세대·분야·매체에 따른 어휘에 대한 이해로 가장 적절한 것은?", opts:["줄임말은 그 자체로 틀린 말이므로 어떤 상황에서도 써서는 안 된다.","전문어는 같은 분야 사람끼리는 정확하고 경제적이지만 바깥사람에게는 소통의 벽이 될 수 있다.","은어는 집단 밖 사람과의 소통을 쉽게 해 준다.","통신 언어는 격식을 갖춘 보고서에도 그대로 쓰는 것이 좋다."], a:1, exp:"어휘의 차이는 '틀림'이 아니라 '양상'이며 기준은 상황·상대에 맞는가이다. 은어는 밖을 배제하고, 통신 언어는 격식 자리에 부적절하다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 자료> 언어 사용 관찰 기록\n㉠ (진료실) 의사: \"경미한 염좌입니다. 냉찜질 후 압박 고정하세요.\" 할머니: \"예? 뭐라고요?\"\n㉡ (단톡방) 지우: \"ㅇㅈ ㅋㅋ 낼 봄\" / 민호: \"ㅇㅋ\"\n㉢ (집) 손자: \"할머니, 이 반찬 완전 꿀맛이에요. 꿀잼!\" 할머니: \"꿀잼이 뭐니?\"\n㉣ (동네 간판) \"Fresh Bakery OPEN\"", q:"자료에 대한 분석으로 옳은 것만 고른 것은?\nㄱ. ㉠은 분야의 전문어가 비전문가에게 소통의 벽이 된 예이다.\nㄴ. ㉡의 줄임말은 매체 특성상 빠르고 친근하지만 격식이 필요한 자리에는 맞지 않는다.\nㄷ. ㉢에서 손자의 말은 틀린 말이므로 써서는 안 된다.\nㄹ. ㉣은 외래어를 바르게 활용한 국어 실천의 예이다.", opts:["ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄷ, ㄹ","ㄱ, ㄴ, ㄹ"], a:0, exp:"㉠전문어의 소통 단절, ㉡매체 어휘의 특성은 옳다. ㉢세대 어휘는 틀린 말이 아니라 상대에 맞게 풀어 쓸 문제이고, ㉣은 우리말로 바꿀 수 있는 외국어를 간판에 쓴 외국어 남용이다.", why3:"'틀린 말·써서는 안 된다'처럼 말 자체를 재단하는 선지는 '양상' 관점과 어긋나므로 먼저 지운다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"위 자료 ㉢에서 손자와 할머니의 소통이 어긋난 원인을 어휘의 양상 측면에서 쓰고, 손자가 보여야 할 바람직한 언어 태도를 두 가지 서술하시오. 또 이 상황이 '언어와 자아'의 관계에서 알려 주는 점을 한 문장으로 쓰시오.", model:"'꿀잼'처럼 세대에 따라 쓰는 신조어·줄임말이 달라 할머니가 뜻을 알지 못한 것이 원인이다. 손자는 첫째, 상대가 모르는 말은 '아주 재미있다는 뜻'이라고 풀어 설명하고, 둘째, 상대와 상황에 맞게 말을 골라 써야 한다. 이는 내가 쓰는 말이 내가 속한 집단과 정체성을 드러내므로, 말을 고르는 일이 곧 상대를 배려하는 나를 만드는 일임을 보여 준다.", rubric:[["원인: 세대 어휘(신조어·줄임말) 차이",3],["태도 ① 풀어 설명",2],["태도 ② 상황·상대에 맞게 조절(관용)",2],["언어와 자아 연결",2],["문장 완결",1]], exp:"'줄임말을 쓰지 말아야 한다'로 쓰면 태도 항목 감점 — 기준은 상황·상대 적합성이다." }
 ],

 "kor-g3-read-synth": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"매체 자료의 **공정성**과 **신뢰성**에 대한 설명으로 옳은 것은?", opts:["믿을 만한 기관이 쓴 글은 한쪽 입장만 실어도 공정성이 높다.","신뢰성은 출처가 믿을 만한가, 공정성은 여러 입장을 균형 있게 다루었는가의 문제이다.","말투가 점잖고 중립적이면 공정성이 보장된다.","사진과 통계가 많을수록 공정성이 높다."], a:1, exp:"신뢰성=출처, 공정성=균형(선택·배제). 믿을 만한 기관도 한쪽만 실으면 공정성이 낮고, 말투가 중립적이어도 사례를 한쪽만 고르면 공정하지 않다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"같은 화제를 다룬 두 글의 관점이 갈리는 **까닭**으로 적절하지 **않은** 것은?", opts:["글쓴이의 처지나 이해관계가 다르다.","글쓴이가 중시하는 가치가 다르다.","글쓴이가 다룬 자료의 범위가 다르다.","두 글의 길이가 다르다."], a:3, exp:"관점 차이는 입장·가치·맥락·자료 범위에서 비롯된다. 글의 길이는 관점과 무관하다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 글 두 편>\n(가) 학교 운동장을 저녁 시간에 주민에게 개방해야 한다. 체육 시설이 부족한 동네에서 학교 운동장은 공공의 자산이다. 주민 설문에서 80%가 개방에 찬성했다.\n(나) 운동장 개방은 학생의 안전을 위협한다. 외부인 출입으로 사고가 난 학교가 실제로 있고, 관리 비용도 학교가 떠안게 된다. 학생의 공간이 먼저다.", q:"(가)의 글쓴이가 (나)를 읽고 보일 반응으로 가장 적절한 것은?", opts:["사고 사례는 출입 관리 방안으로 보완할 수 있으며, 주민의 체육 시설 부족 문제도 함께 고려해야 한다.","학생 안전이 가장 중요하므로 개방 주장을 철회하겠다.","관리 비용은 문제가 되지 않으므로 (나)의 근거는 모두 거짓이다.","(나)의 글쓴이는 주민 설문에 참여하지 않았으므로 의견을 낼 자격이 없다."], a:0, exp:"(가)는 공공성·주민 편의를 중시하므로 (나)의 안전 우려를 관리 방안으로 보완하며 자기 관점을 유지한다. ②는 관점 포기, ③은 근거 없는 부정, ④는 인신공격.", why3:"'글쓴이의 반응' 문항은 그 글의 관점(중시하는 가치)을 끝까지 유지한 선지를 고른다.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"위 (가)와 (나)의 관점 차이를 각 글이 중시하는 가치와 근거를 들어 쓰고, 그 차이가 생긴 까닭을 글쓴이의 입장과 관련지어 서술하시오. 마지막으로 두 글을 종합한 자신의 판단을 한 문장으로 쓰시오.", model:"(가)는 공공성과 주민 편의를 중시하여 설문 결과를 근거로 개방에 찬성하고, (나)는 학생 안전과 학교의 부담을 중시하여 사고 사례와 비용을 근거로 반대한다. (가)는 주민의 처지에서, (나)는 학교·학생의 처지에서 쓰였기 때문에 같은 운동장을 두고 관점이 갈린다. 나는 출입 관리와 비용 분담 조건을 갖춘 뒤 제한적으로 개방하는 것이 두 가치를 함께 살리는 길이라고 본다.", rubric:[["(가) 가치+근거",2],["(나) 가치+근거",2],["차이의 원인(글쓴이 입장)",3],["종합한 자기 판단",2],["문장 완결",1]], exp:"두 글을 요약만 나란히 쓰면 '비교'가 아니다. 원인과 자기 판단까지 써야 주제 통합적 읽기." }
 ],

 "kor-g3-speak-persuade": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"광고 문구 \"30년 경력 제빵 명장이 만든 빵, 설문 조사 응답자 92%가 '다시 사고 싶다'고 답했습니다.\"에 쓰인 설득 전략을 **모두** 고른 것은?", opts:["이성적 설득만","감성적 설득만","인성적 설득과 이성적 설득","감성적 설득과 인성적 설득"], a:2, exp:"'30년 경력 명장'은 만든 사람의 전문성에 기댄 인성적 설득, '92%'는 수치를 근거로 한 이성적 설득. 정서를 자극하는 부분은 없다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"진로 탐색을 위해 소방관을 면담하려는 학생의 질문 계획에 대한 평가로 가장 적절한 것은?\n① 소방관이 되려면 어떤 준비가 필요한가요? ② 일이 힘든가요? ③ 가장 기억에 남는 출동은 무엇이었고 왜 그런가요? ④ 좋아하는 음식은 무엇인가요?", opts:["②는 개방형 질문이므로 깊은 정보를 얻기에 알맞다.","④는 면담 목적과 관련이 없으므로 빼거나 바꾸어야 한다.","③은 예/아니오로 답할 수 있어 확인용으로 적절하다.","①은 상대를 불편하게 하므로 면담 예절에 어긋난다."], a:1, exp:"④는 진로 탐색이라는 목적과 무관. ②는 예/아니오로 끝나는 폐쇄형이라 개방형으로 고쳐야 하고, ③은 개방형이며, ①은 목적에 맞는 적절한 질문.", err:"추론" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 공익 캠페인 연설>\n㉠ 저는 10년 동안 우리 지역 하천을 정화해 온 환경 단체 활동가입니다. ㉡ 지난해 이 하천에서 수거한 쓰레기는 3톤이 넘습니다. ㉢ 여러분의 아이들이 맨발로 뛰놀던 그 물가가 지금은 악취로 가득합니다. ㉣ 매달 첫째 주 토요일, 한 시간만 함께해 주십시오.", q:"연설에 쓰인 설득 전략에 대한 분석으로 옳은 것만 고른 것은?\nㄱ. ㉠은 화자의 경력으로 신뢰를 얻는 인성적 설득이다.\nㄴ. ㉡은 수치를 근거로 제시한 이성적 설득이다.\nㄷ. ㉢은 청중의 정서를 자극하는 감성적 설득이다.\nㄹ. ㉣은 통계를 제시한 이성적 설득이다.", opts:["ㄱ, ㄴ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"], a:1, exp:"㉠화자 자신의 전문성(인성), ㉡'3톤'이라는 수치(이성), ㉢아이들·악취로 정서 환기(감성). ㉣은 실천을 요청하는 문장으로 통계가 없다.", why3:"문장마다 '수치·사례/느낌·장면/나는 ○○'로 표시하면 전략이 갈린다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"위 연설의 ㉠~㉢에 쓰인 설득 전략을 각각 쓰고, 이 연설을 비판적으로 들을 때 청중이 확인해야 할 점을 두 가지 서술하시오.", model:"㉠은 화자의 경력을 내세운 인성적 설득, ㉡은 수치를 근거로 한 이성적 설득, ㉢은 정서에 호소하는 감성적 설득이다. 비판적으로 들을 때는 첫째, '3톤'이라는 수치의 출처와 조사 방법이 믿을 만한지 확인해야 하고, 둘째, ㉢의 정서적 호소가 근거 없이 감정만 자극하는 것은 아닌지, 즉 주장(참여 요청)과 근거의 연결이 타당한지 따져야 한다.", rubric:[["㉠~㉢ 전략 명칭 각 정확",3],["확인점 ① 수치의 출처·신뢰성",3],["확인점 ② 감정 호소의 근거·타당성",3],["문장 완결",1]], exp:"'감성적 설득은 나쁘다'로 쓰면 감점. 근거 없이 감정만 자극하는지가 판단 기준이다." }
 ],

 /* ===================== 고1 (kor-h1.js) ===================== */
 "kor-h1-debate": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 발언에 나타난 논리적 오류는?\n\"급식에 채식 메뉴를 늘려야 합니다. 채식 메뉴가 늘어나는 것은 좋은 일이기 때문입니다.\"", opts:["성급한 일반화","순환 논증","잘못된 인과","무관한 권위에의 호소"], a:1, exp:"주장(채식 메뉴 확대)을 근거 자리에 말만 바꿔 다시 놓았으므로 순환 논증. 근거가 주장과 독립적이어야 논증이 성립한다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"논제 '교내 휴대 전화 사용을 전면 허용해야 한다'의 찬성 측이 \"우리 학교 체육관은 작년에 새로 지어졌습니다.\"라는 사실을 근거로 들었다. 이 논증 평가로 가장 적절한 것은?", opts:["근거가 사실이므로 타당한 논증이다.","근거가 사실이어도 주장과 관련이 없어 타당하지 않다.","근거의 양이 부족할 뿐 관련성은 충분하다.","근거의 출처가 불분명해 신뢰성이 낮다."], a:1, exp:"타당성은 신뢰성·관련성·충분성을 함께 따진다. 체육관 신축은 참이지만 휴대 전화 허용과 무관하므로 관련성이 없다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 토론> 논제: 교내에 음료 자판기를 설치해야 한다.\n찬성 1(입론): 전교생 설문에서 72%가 매점이 멀어 불편하다고 답했습니다. 자판기는 전기만 있으면 설치할 수 있고 관리는 업체가 맡습니다.\n반대 1(반대 신문): 설문은 몇 명을 대상으로 했습니까? 그리고 당 함량이 높은 음료가 늘어 건강에 해롭지는 않습니까?\n찬성 1: 500명 중 420명이 응답했습니다. 무가당 음료만 넣으면 됩니다.", q:"토론에 대한 설명으로 가장 적절한 것은?", opts:["찬성 1의 입론은 문제의 심각성과 실행 가능성은 다루었으나 효과·이익의 쟁점은 입증하지 않았다.","반대 1은 반대 신문에서 자신의 새로운 주장을 길게 펼치고 있다.","찬성 1의 설문은 표본이 적어 성급한 일반화에 해당한다.","반대 1의 두 번째 질문은 논제와 무관한 논점 일탈이다."], a:0, exp:"입론에 '불편(심각성)'과 '설치·관리(실행 가능성)'는 있으나 설치로 얻는 이익·부작용 비교는 없다. 반대 신문은 질문으로 검증 중이고(②×), 500명 중 420명은 충분한 표본(③×), 건강 문제는 효과·부작용 쟁점에 속한다(④×).", why3:"정책 논제는 심각성·실행 가능성·효과 세 칸을 그려 입론에서 빈칸을 찾는다.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"위 토론에서 찬성 측 입론이 다루지 않은 필수 쟁점의 이름을 쓰고, 그 쟁점을 입증하는 근거 문장을 하나 작성하시오. 또 반대 1의 첫 번째 질문이 찬성 측 논증의 어떤 요소를 검증하려는 것인지 서술하시오.", model:"다루지 않은 쟁점은 '효과·이익'이다. 근거 예: 자판기를 설치한 인근 학교에서 쉬는 시간 매점 이동으로 인한 지각이 30% 줄었다는 조사 결과가 있다. 반대 1의 첫 질문은 설문의 대상과 규모를 물어 근거의 충분성과 신뢰성, 즉 72%라는 수치가 전교생의 의견을 대표하는지를 검증하려는 것이다.", rubric:[["쟁점 이름: 효과·이익",2],["근거 문장(효과를 보이는 구체 근거)",3],["질문의 의도: 근거의 충분성·신뢰성 검증",3],["반대 신문=질문으로 검증임을 반영",1],["문장 완결",1]], exp:"쟁점을 '실행 가능성'으로 쓰면 0점(입론에 이미 있음). 근거 문장은 '~해야 한다' 같은 주장이 아니라 사실·사례여야 한다." }
 ],

 "kor-h1-presentation-argue": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"학생회(입장: 축제 예산 20% 증액)와 학교(입장: 예산 동결)의 협상에서, 학생회의 이해관계는 '무대 장비 대여비 상승', 학교의 이해관계는 '다른 행사 예산 보호'이다. 가장 적절한 **대안**은?", opts:["학생회가 요구를 완전히 철회하고 예산 동결을 받아들인다.","무대 장비를 지역 문화 센터에서 무상 대여해 추가 예산 없이 무대를 꾸민다.","다수결로 학생회 요구를 통과시킨다.","학교가 다른 행사 예산을 모두 줄여 축제에 몰아준다."], a:1, exp:"대안은 입장이 아니라 이해관계 수준에서 찾는다. ②는 장비 문제(학생회)와 예산 보호(학교)를 동시에 만족. ①④는 한쪽 희생, ③은 협상이 아니다.", err:"추론" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"논증하는 글에서 '예상 반론과 재반박'이 **완성된** 것은?", opts:["물론 등교 시간을 늦추면 하교도 늦어진다는 반론이 있다.","등교 시간을 늦추어야 한다는 데는 반론의 여지가 없다.","물론 하교가 늦어진다는 반론이 있다. 그러나 수면이 늘면 집중도가 오른다는 조사가 있어 효과가 더 크다.","하교가 늦어진다는 반론은 틀렸다."], a:2, exp:"반론을 소개하고('물론 ~') 근거를 들어 되받아쳐야('그러나 ~이므로') 완성. ①은 소개만, ②는 반론 부정, ④는 근거 없는 반박.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 초고> 학교 도서관을 밤 9시까지 열어야 한다. 늦게까지 공부할 곳이 없기 때문이다.\n<교사 조언> 예상 반론(관리 인력 부담)을 수용해 재반박하고, 통계와 비유를 하나씩 넣을 것.\n<고쳐 쓴 문장>\n㉠ 도서관은 지식의 등대이므로 밤에도 열어야 한다. 학생 63%가 자습 공간이 없다고 답했다.\n㉡ 물론 관리 인력 부담이 커진다는 반론이 있다. 그러나 학생 63%가 자습 공간이 없다고 답한 만큼, 등대가 밤에 더 필요하듯 도서관도 밤에 더 필요하며 부담은 자원봉사 제도로 나눌 수 있다.\n㉢ 관리 인력 부담이 크다는 반론도 있지만 학생들의 요구가 크므로 열어야 한다.\n㉣ 학생 63%가 자습 공간이 없다고 답했다. 인력 부담은 자원봉사로 해결된다.", q:"교사의 조언을 **모두** 반영하여 고쳐 쓴 문장은?", opts:["㉠","㉡","㉢","㉣"], a:1, exp:"㉡만 반론 수용('물론')+재반박('그러나 ~자원봉사')+통계(63%)+비유(등대)를 모두 갖췄다. ㉠비유·통계만, ㉢통계·비유 없고 재반박 근거 없음, ㉣반론 수용 표현과 비유 없음.", why3:"조건에 번호를 붙여 선지마다 ○×표를 만들고 하나라도 ×면 지운다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"동아리(요구: 연습실 매일 사용)와 학교(요구: 주 2회만 허용)가 협상한다. 동아리는 대회가 한 달 남았고, 학교는 다른 동아리와의 형평과 야간 안전을 걱정한다. 양측의 입장과 이해관계를 구분하여 쓰고, 두 이해관계를 함께 만족시키는 대안을 근거와 함께 제시하시오.", model:"동아리의 입장은 매일 사용, 이해관계는 대회 전 집중 연습이다. 학교의 입장은 주 2회 허용, 이해관계는 다른 동아리와의 형평과 야간 안전이다. 대안으로 대회 전 한 달만 한시적으로 주 4회, 그중 야간은 교사 입회 아래 2회로 제한하면, 동아리는 연습량을 확보하고 학교는 형평(기간 한정)과 안전(입회)을 지킬 수 있다.", rubric:[["양측 입장 구분",2],["양측 이해관계 구분",3],["대안이 양쪽 이해관계를 동시에 충족",3],["대안의 근거(왜 충족되는지)",1],["문장 완결",1]], exp:"'절충해서 주 3회'처럼 입장만 중간으로 자르면 이해관계 항목 감점. 기간·조건을 붙여 양쪽 이유를 해결해야 한다." }
 ],

 "kor-h1-read-literal": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"\"전기 자동차는 주행 중 배기가스를 내지 않는다. 반면 내연 기관 자동차는 연료를 태워 배기가스를 낸다. 다만 전기를 만드는 과정의 배출까지 고려하면 차이는 줄어든다.\" 이 글의 전개 방식으로 가장 적절한 것은?", opts:["전기차와 내연 기관차의 배출을 대조한 뒤 조건을 덧붙여 차이를 한정한다.","전기차의 작동 원리를 과정에 따라 설명한다.","전기차와 수소차의 장단점을 비교한다.","배기가스의 종류를 기준에 따라 분류한다."], a:0, exp:"'반면'으로 두 대상을 대조하고 '다만'으로 한정. ③은 방식(비교)은 그럴듯하나 대상(수소차)이 글에 없다 — 방식과 대상을 모두 확인해야 한다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"\"해안 사구는 바람이 모래를 옮겨 쌓은 언덕이다. 사구의 식물은 뿌리로 모래를 붙잡아 사구가 무너지는 것을 막는다. 그래서 사구 식물이 훼손되면 사구는 빠르게 깎인다.\" 이 글에서 추론할 수 있는 것은?", opts:["사구는 파도가 모래를 밀어 올려 만든다.","사구 식물을 복원하면 사구의 침식을 늦출 수 있을 것이다.","사구 식물은 모래를 옮겨 사구를 만든다.","바람이 약한 해안일수록 사구가 크다."], a:1, exp:"식물의 뿌리가 모래를 붙잡아 무너짐을 막는다는 문장에서 복원→침식 완화를 추론할 수 있다. ①바람이 만든다, ③식물은 붙잡는 역할, ④지문에 근거 없음.", err:"추론" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 지문> 기회비용이란 어떤 선택을 할 때 포기하는 대안 가운데 가장 가치가 큰 것을 말한다. 예컨대 토요일 오후에 영화 관람, 아르바이트(3만 원), 독서 가운데 영화를 택했다면 기회비용은 포기한 것 중 가장 큰 아르바이트의 3만 원이다. 포기한 대안을 모두 더하지 않고 가장 큰 하나만 센다는 점이 중요하다. 따라서 합리적 선택은 선택에서 얻는 이익이 기회비용보다 클 때 이루어진다.\n\n<보기> 민재는 주말에 ㉠ 친구와 놀기(만족 2만 원어치), ㉡ 과외 아르바이트(4만 원), ㉢ 집에서 쉬기(만족 1만 원어치) 중 ㉠을 택했다.", q:"윗글을 바탕으로 <보기>를 이해한 내용으로 옳은 것만 고른 것은?\nㄱ. 민재의 기회비용은 4만 원이다.\nㄴ. 민재의 기회비용은 ㉡과 ㉢을 더한 5만 원이다.\nㄷ. 글의 기준에 따르면 민재의 선택은 합리적이지 않다.\nㄹ. 민재가 ㉢을 택했다면 기회비용은 2만 원이다.", opts:["ㄱ, ㄷ","ㄱ, ㄹ","ㄴ, ㄷ","ㄴ, ㄹ"], a:0, exp:"포기한 대안 중 가장 큰 ㉡ 4만 원이 기회비용(ㄱ, ㄴ×). 이익 2만 < 기회비용 4만이므로 합리적이지 않다(ㄷ). ㉢을 택해도 포기한 것 중 최대는 ㉡ 4만 원(ㄹ×).", why3:"지문의 조건('가장 큰 하나만')을 한 줄로 적고 <보기>의 수치를 그 조건에 대입한다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"위 <자작 지문>(기회비용)에 쓰인 내용 전개 방식을 세 가지 찾아, 각 방식이 쓰인 문장의 표지(단서가 되는 표현)를 지문에서 인용하여 서술하시오.", model:"첫째, '기회비용이란 ~을 말한다'에서 '~란 ~을 말한다'는 표지로 개념을 정의하였다. 둘째, '예컨대 토요일 오후에 ~'에서 '예컨대'를 표지로 구체적 예시를 들었다. 셋째, '따라서 합리적 선택은 ~'에서 '따라서'를 표지로 앞 내용에서 결론을 끌어내는 인과(논리적 귀결)의 방식을 썼다.", rubric:[["정의 + 표지 인용",3],["예시 + 표지 인용",3],["인과(귀결) + 표지 인용",3],["문장 완결",1]], exp:"방식 이름만 나열하고 표지를 인용하지 않으면 각 1점. '대조·분류'처럼 지문에 없는 방식을 쓰면 해당 항목 0점." }
 ],

 "kor-h1-read-critical": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"비판적 읽기에 대한 이해로 가장 적절한 것은?", opts:["글쓴이의 주장에 반대하는 결론을 내려야 비판적 읽기이다.","타당성·공정성·신뢰성의 기준으로 평가한 결과 글쓴이에게 동의할 수도 있다.","출처가 분명한 자료를 쓴 글은 비판적으로 읽을 필요가 없다.","글쓴이의 의도를 짐작하는 것은 비판적 읽기가 아니다."], a:1, exp:"비판은 '반대'가 아니라 기준에 따른 평가이므로 동의도 가능하다. 출처가 분명해도 선택·배제나 관련성은 따로 따져야 하며, 의도 파악은 비판적 읽기의 일부다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"어느 기사의 막대그래프는 세로축이 90에서 시작하며 작년 92, 올해 95를 나타내고, 제목은 '학교 폭력 급증'이다. 이 복합양식 자료에 대한 평가로 가장 적절한 것은?", opts:["막대 길이 차이가 크므로 '급증'이라는 제목은 타당하다.","세로축을 90에서 시작해 약 3%의 변화를 과장해 보이게 했으므로 표현 방법의 의도를 의심해야 한다.","숫자가 제시되었으므로 그래프는 항상 객관적이다.","제목은 글쓴이의 관점과 무관하다."], a:1, exp:"y축 시작점을 잘라 작은 변화를 크게 보이게 한 표현 방법이며, 제목도 그 관점을 강화한다. 복합양식 읽기는 수치와 표현 방식을 함께 평가한다.", err:"자료" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 글 두 편>\n(가) 학교 급식에 채식 선택제를 도입해야 한다. 육류 생산은 온실가스 배출의 큰 부분을 차지하므로, 채식 선택제는 학교가 할 수 있는 기후 위기 대응이다.\n(나) 채식 선택제는 급식 단가를 올리고 조리 인력을 늘려야 하므로 현실적으로 어렵다. 잔반 줄이기가 비용 대비 더 효과적인 환경 실천이다.\n\n<보기> 어떤 환경 정책이든 비용 대비 효과를 따져야 하며, 효과가 큰 정책도 실행 조건이 갖춰지지 않으면 실패한다.", q:"<보기>를 바탕으로 (가)와 (나)를 평가한 내용으로 가장 적절한 것은?", opts:["(가)는 효과는 강조했으나 비용과 실행 조건을 다루지 않았으므로 <보기>의 기준에서 보완이 필요하다.","(나)는 비용만 말하고 효과는 전혀 고려하지 않았으므로 <보기>와 무관하다.","<보기>는 (가)의 주장을 전면적으로 지지한다.","(가)와 (나)는 모두 환경 실천이 불필요하다고 본다."], a:0, exp:"(가)에는 단가·인력 같은 실행 조건 논의가 없다. (나)는 '비용 대비 효과'를 들어 대안을 제시했으므로 효과도 고려(②×). <보기>는 기준이지 지지 선언이 아니며(③×), 두 글 모두 환경 실천 자체는 인정한다(④×).", why3:"<보기>를 '평가 기준 두 개'로 쪼개고 각 글에 빠진 기준을 찾는다.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"위 (가)의 글쓴이 주장에 대해, 근거의 한계를 하나 지적하여 비판하고 그 한계를 보완하는 데 필요한 자료의 종류를 구체적으로 쓰시오. 다음 틀을 활용하시오: '글쓴이는 ①을 근거로 ②를 주장한다. 그러나 ①은 ③이라는 한계가 있으므로 ④ 자료로 보완해야 한다.'", model:"글쓴이는 육류 생산이 온실가스 배출의 큰 부분을 차지한다는 점을 근거로 급식 채식 선택제 도입을 주장한다. 그러나 이 근거는 전체 산업의 배출 통계일 뿐 한 학교 급식의 메뉴 변경이 실제로 얼마나 배출을 줄이는지를 보여 주지 못한다는 한계가 있으므로, 채식 선택제를 시행한 학교의 급식 관련 배출량 변화와 단가·인력 비용 자료로 보완해야 한다.", rubric:[["근거와 주장 정확히 정리",2],["한계 지적(범위·관련성 문제)",4],["보완 자료의 종류 구체적",3],["문장 완결",1]], exp:"'근거가 틀렸다'처럼 근거를 부정만 하면 감점. 근거가 참이어도 주장과의 거리(관련성·범위)를 짚어야 한다." }
 ],

 "kor-h1-lit-genre": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 시의 시상 전개 방식으로 가장 적절한 것은?\n\n강 건너 불빛은 밤마다 켜지고\n강 이쪽 내 방의 불은 꺼진 지 오래다\n건너가려 해도 다리는 없고\n나는 꺼진 불을 켜지 않는다", opts:["앞부분에서 풍경을, 뒷부분에서 정서를 제시하는 선경후정","'강 건너'와 '강 이쪽'을 맞세워 화자의 처지를 드러내는 대비","첫 행과 끝 행을 같게 하는 수미상관","감정의 강도를 점점 높여 가는 점층"], a:1, exp:"켜진 불/꺼진 불, 건너/이쪽의 대비가 단절과 체념을 드러낸다. 풍경과 정서가 분리되어 있지 않고, 첫·끝 행이 같지 않으며 점층도 없다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"소설의 한 장면 \"그는 말없이 문을 닫았다. 가슴속에서는 억울함과 미안함이 뒤엉켜 있었다.\"를 시나리오로 각색할 때 반드시 달라지는 점은?", opts:["갈등이 사라진다.","서술자가 전하던 인물의 속마음을 대사·표정 지시문·촬영 기법으로 보여 주어야 한다.","사건의 순서를 반드시 뒤집어야 한다.","인물의 이름을 바꾸어야 한다."], a:1, exp:"극 갈래에는 서술자가 없어 내면 서술('뒤엉켜 있었다')을 대사, 지시문(표정·행동), 클로즈업 등으로 바꾸어야 한다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 시>\n봄은 왔다고 다들 말하는데\n내 창가의 화분은 아직 마른 흙\n물을 주어야 할까, 기다려야 할까\n햇살만 자꾸 창틀을 두드린다\n\n<보기> 시에서 자연물은 화자의 내면을 비추는 거울이 되기도 하며, 화자의 태도가 바뀌는 지점은 시상 전개의 전환점이 된다.", q:"<보기>를 참고하여 윗글을 감상한 내용으로 적절하지 **않은** 것은?", opts:["'다들 말하는데'와 '아직 마른 흙'의 대비로 바깥 세계와 화자 내면 사이의 거리가 드러난다.","'마른 흙'은 화자의 메마른 내면을 비추는 자연물로 읽을 수 있다.","3행의 물음은 화자의 망설임을 보여 주며, 이 지점에서 시상이 확신으로 전환된다.","'햇살이 창틀을 두드린다'는 외부의 변화가 화자를 재촉하는 것으로 의인화되었다."], a:2, exp:"3행은 망설임을 보여 주지만 4행까지 화자는 여전히 행동하지 않으므로 '확신으로 전환'은 작품 사실과 어긋난다. 나머지는 <보기>와 시구가 맞게 연결된다.", why3:"선지의 앞부분(구절 사실)이 맞아도 뒷부분(해석)이 작품과 어긋나면 오답.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"위 <자작 시>(봄은 왔다고)의 시상 전개 방식을 쓰고, 그 방식이 드러나는 행을 지목하여 주제(화자의 정서·태도)와 연결해 서술하시오.", model:"이 시는 대비의 방식으로 시상을 전개한다. 1행의 '봄은 왔다'는 바깥 세계와 2행의 '아직 마른 흙'인 화자의 내면이 맞세워지고, 4행에서 재촉하는 '햇살'과 망설이는 화자가 다시 대비된다. 이 대비를 통해 세상의 변화를 따라가지 못하고 머뭇거리는 화자의 내면과 망설임이 주제로 드러난다.", rubric:[["전개 방식: 대비",2],["대비가 드러나는 행 지목(1·2행 또는 4행)",3],["주제(망설임·거리감)와 연결",4],["문장 완결",1]], exp:"방식 이름만 쓰면 2점. '어느 행에서, 무엇과 무엇이, 그래서 어떤 정서'의 세 단계를 갖춰야 만점." }
 ],

 "kor-h1-lit-history": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"고전 시가의 갈래와 특징이 바르게 연결된 것은?", opts:["향가 — 사대부가 한문투로 지었고 후렴구가 있다.","고려가요 — 향찰로 표기된 신라의 노래이다.","가사 — 4음보가 길이 제한 없이 이어지는 연속체이다.","경기체가 — 평민의 솔직한 정서를 구전으로 전했다."], a:2, exp:"가사는 4음보 연속체. ①은 경기체가, ②는 향가, ④는 고려가요의 특징을 바꿔 놓은 것.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"시대와 문학 경향의 연결로 가장 적절한 것은?", opts:["개화기 — 자연 속 삶의 만족을 노래한 강호한정의 시조가 처음 등장","1920년대 — 창가·신체시로 개화 계몽을 노래","광복·전쟁 이후 — 분단과 전쟁의 상처를 다룬 문학","조선 후기 — 향찰로 표기된 10구체 향가의 유행"], a:2, exp:"분단 문학은 광복·전쟁 이후. 강호한정 시조는 조선 전기 사대부, 창가·신체시는 개화기, 향가는 신라의 갈래.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 고전풍 노래>\n임 계신 곳 바라보니 구름만 겹겹이라\n산 넘고 물 건너서 이 몸이 왔건마는\n달 밝은 밤이면 그리움만 길어지고\n북녘 하늘 기러기야 내 소식 전해 다오\n\n<보기> 이 노래는 조선 시대 한 사대부가 임금의 노여움을 사 남쪽으로 유배된 뒤 지은 것으로 전한다. 당시 노래 속 '임'은 흔히 임금을 뜻했다.", q:"<보기>를 참고하여 윗글을 감상한 내용으로 적절하지 **않은** 것은?", opts:["'임 계신 곳'을 가리는 '구름'은 화자와 임금 사이를 가로막는 장애물로 볼 수 있다.","'기러기'는 화자의 마음을 임에게 전해 줄 매개물이다.","4음보가 이어지는 형식과 임금을 그리는 연군의 정서가 나타난다.","'산 넘고 물 건너서 이 몸이 왔건마는'은 화자가 유배에서 풀려나 임금 곁으로 돌아왔음을 뜻한다."], a:3, exp:"'왔건마는'은 유배지로 왔다는 뜻이며 뒤에 그리움이 이어지므로 임금 곁으로 돌아온 것이 아니다. 구름=장애물, 기러기=매개물, 연군·4음보는 <보기>와 맞게 연결된다.", why3:"<보기>의 '유배'를 작품에 넣을 때 화자가 '어디에 있는가'부터 고정한다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"위 <자작 고전풍 노래>를 <보기>와 다른 관점, 즉 '임'을 임금이 아닌 헤어진 연인으로 보는 관점에서 해석하고, 그 해석을 뒷받침하는 구절을 둘 이상 인용하시오. 또 두 해석이 갈리는 까닭을 해석의 근거 유형으로 설명하시오.", model:"'임'을 헤어진 연인으로 보면, 이 노래는 먼 곳으로 떠나와 연인을 그리워하는 이별의 노래가 된다. '달 밝은 밤이면 그리움만 길어지고'는 밤마다 깊어지는 사랑의 그리움으로, '기러기야 내 소식 전해 다오'는 연인에게 안부를 전하고 싶은 마음으로 읽힌다. <보기>의 해석은 작가의 유배라는 외적 맥락(작가·시대)에 기댄 것이고, 이 해석은 작품의 구절 자체에만 기댄 내적 해석이므로 근거 유형이 달라 해석이 갈린다.", rubric:[["연인으로 보는 해석 제시",2],["구절 인용 ① + 의미",2],["구절 인용 ② + 의미",2],["해석 차이의 원인: 외적 맥락 vs 내적 근거",3],["문장 완결",1]], exp:"구절 인용 없이 '사랑 노래로도 읽힌다'만 쓰면 2점. 근거 유형(작가·시대/작품 자체)을 명시해야 만점." }
 ],

 "kor-h1-phonology-word": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"'닭만[당만]'에 일어난 음운 변동과 음운 수 변화를 바르게 설명한 것은?", opts:["비음화(교체) 한 가지만 일어나 음운 수가 같다.","자음군 단순화(탈락) 뒤 비음화(교체)가 일어나 음운 수가 하나 줄었다.","ㄴ 첨가 뒤 비음화가 일어나 음운 수가 하나 늘었다.","거센소리되기(축약)가 일어나 음운 수가 하나 줄었다."], a:1, exp:"겹받침 ㄺ에서 ㄹ이 탈락해 [닥만], ㄱ이 ㅁ 앞에서 ㅇ으로 바뀌어 [당만]. 탈락(−1)+교체(0)로 7개→6개.", err:"계산" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"단어의 짜임에 대한 설명으로 옳은 것은?", opts:["'덮개'는 동사 어근에 접미사가 붙어 명사가 된 파생어이다.","'맨손'은 접두사가 붙으면서 품사가 바뀐 파생어이다.","'덮밥'은 관형사형 어미가 있어 통사적 합성어이다.","'힘들다'는 어간에 어미 없이 어근이 붙은 비통사적 합성어이다."], a:0, exp:"'덮-'+'-개'→명사, 접미 파생은 품사가 바뀔 수 있다. ②접두 파생은 품사 유지, ③'덮밥'은 어미 없이 붙은 비통사적, ④'힘(이) 들다'는 주어+서술어 구조의 통사적 합성어.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<보기> 음운 변동은 교체(개수 같음)·탈락(−1)·첨가(+1)·축약(−1)으로 나뉘며, 한 단어에 둘 이상이 겹칠 수 있다.\n\n<자료> 변동 전·후 음운 수\n| 단어 | 발음 | 음운 수 |\n|---|---|---|\n| ㉠ 국화 | [구콰] | 5 → 4 |\n| ㉡ 맏이 | [마지] | 4 → 4 |\n| ㉢ 흙과 | [흑꽈] | 6 → 5 |\n| ㉣ 색연필 | [생년필] | 8 → 9 |", q:"<보기>를 바탕으로 자료를 탐구한 내용으로 옳은 것만 고른 것은?\nㄱ. ㉠은 ㄱ과 ㅎ이 ㅋ으로 합쳐진 축약이다.\nㄴ. ㉡은 ㄷ이 형식 형태소 ㅣ 앞에서 ㅈ으로 바뀐 구개음화로, 음운 수가 같다.\nㄷ. ㉢에서는 탈락만 일어났다.\nㄹ. ㉣은 ㄴ 첨가 뒤 비음화가 일어나 음운 수가 하나 늘었다.", opts:["ㄱ, ㄴ","ㄷ, ㄹ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ"], a:2, exp:"㉠축약(−1), ㉡구개음화는 교체(0), ㉣ㄴ 첨가(+1)+비음화(0)=+1. ㉢은 ㄹ 탈락(−1)에 더해 ㄱ 뒤의 ㄱ이 ㄲ으로 된소리되기(교체)도 일어나므로 '탈락만'은 틀림.", why3:"음운 수 변화가 맞아도 '~만 일어났다'는 겹친 교체를 놓친 선지일 수 있다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"계산", q:"'밭일'의 표준 발음을 [ ] 안에 쓰고, 적용된 음운 변동을 일어나는 순서대로 유형과 함께 서술하시오. 또 변동 전후의 음운 수 변화를 계산 과정과 함께 쓰시오.", model:"표준 발음은 [반닐]이다. 첫째, 음절의 끝소리 규칙으로 받침 ㅌ이 ㄷ으로 바뀌고(교체, [받일]), 둘째, '일' 앞에 ㄴ이 덧붙어(첨가, [받닐]), 셋째, ㄷ이 ㄴ 앞에서 ㄴ으로 바뀐다(비음화·교체, [반닐]). 변동 전 음운은 ㅂ·ㅏ·ㅌ·ㅣ·ㄹ 5개, 변동 후는 ㅂ·ㅏ·ㄴ·ㄴ·ㅣ·ㄹ 6개로 첨가에 의해 하나 늘었다.", rubric:[["발음 [반닐]",2],["끝소리 규칙 → ㄴ 첨가 → 비음화 순서",3],["각 변동의 유형(교체·첨가·교체)",2],["음운 수 5→6 계산",2],["문장 완결",1]], exp:"비음화를 ㄴ 첨가보다 먼저 쓰면 순서 항목 감점(ㄴ이 생겨야 비음화 환경이 만들어짐). 음운 수는 글자가 아니라 소리로 센다." }
 ],

 "kor-h1-sentence-norm": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"\"할머니께서 어머니께 선물을 드리셨습니다.\"의 높임 표현에 대한 설명으로 옳은 것은?", opts:["'께서'와 '-시-'는 객체인 어머니를 높인다.","'드리다'와 '께'는 객체인 어머니를 높인다.","'-습니다'는 주체인 할머니를 높인다.","이 문장에는 상대 높임이 쓰이지 않았다."], a:1, exp:"주체(할머니)는 '께서·-시-'로, 객체(어머니)는 '께·드리다'로, 상대(듣는 이)는 '-습니다'로 높였다. 누가·누구에게·듣는 이 셋을 각각 대응시킨다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"밑줄 친 성분이 **보어**인 것은?", opts:["물이 **얼음으로** 변했다.","그는 끝내 **의사가** 되었다.","동생은 **형과** 많이 닮았다.","**바람이** 세차게 분다."], a:1, exp:"보어는 '되다/아니다' 앞의 '이/가' 성분. ①'얼음으로'는 부사어, ③'형과'는 필수적이지만 부사어, ④는 주어.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 대화>\n지수: 어제 ㉠그 책 다 읽었어?\n민호: 응. 선생님께서 ㉡추천해 주신 책이잖아. 내일 ㉢여쭤보고 다음 책도 빌릴래.\n지수: 나도 같이 가도 ㉣돼?\n민호: 그럼, 같이 가자.", q:"대화의 ㉠~㉣에 대한 설명으로 적절하지 **않은** 것은?", opts:["㉠'그'는 두 사람이 함께 알고 있는 대상을 가리키는 지시 표현이다.","㉡에는 '-시-'가 쓰여 행위의 주체인 선생님을 높였다.","㉢'여쭤보고'는 특수 어휘로 객체인 선생님을 높인 표현이다.","㉣'돼'는 '되어'의 준말이 아니므로 '되'로 고쳐 써야 한다."], a:3, exp:"'가도 돼?'는 '되어?'의 준말이므로 '돼'가 맞다('해'를 넣어 자연스러움). ㉠은 담화 맥락상 공유 대상 지시, ㉡은 주체 높임, ㉢은 객체 높임의 특수 어휘.", why3:"되/돼는 '하/해' 대치로 확인 — '가도 해?'가 자연스러우면 '돼'.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"'나는 동생이 그린 그림이 상을 받았다는 소식을 들었다.'의 짜임을 분석하시오. 서술어의 개수를 세어 절의 수를 밝히고, 안긴문장을 모두 찾아 종류와 문장 속 역할을 쓰며, 생략된 성분이 있으면 복원하시오.", model:"서술어는 '그린·받았다·들었다' 셋이므로 절이 세 개인 겹문장이다. '동생이 그린'은 '그림'을 꾸미는 관형절로, '동생이 (그림을) 그렸다'에서 목적어가 생략되었다. '동생이 그린 그림이 상을 받았다는'은 '소식'을 꾸미는 관형절(관형어 역할)이며 그 안에 앞의 관형절이 다시 안겨 있다. 전체는 이 관형절들을 안은 안은문장이다.", rubric:[["서술어 3개 → 절 3개",2],["관형절 '동생이 그린' + 역할",2],["관형절 '~받았다는' + 역할",3],["생략 성분 '그림을' 복원",2],["문장 완결",1]], exp:"'~받았다는'을 인용절로 쓰면 해당 항목 감점(체언 '소식'을 꾸미므로 관형절). 절의 포함 관계(안긴문장 속 안긴문장)를 밝히면 가산." }
 ],

 /* ===================== 고2 (kor-h2.js) ===================== */
 "kor-h2-hwaeon-phoneme": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"표준 발음법에 맞는 것은?", opts:["읽는[일른]","밟다[발따]","읽고[일꼬]","넓다[넙따]"], a:2, exp:"'읽고'는 ㄺ이 ㄱ 앞에서 [ㄹ]로 발음되어 [일꼬]. '읽는'은 [잉는], '밟다'는 [밥따], '넓다'는 [널따]가 표준 발음. 겹받침은 환경에 따라 예외 조항이 있다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"**유음화**만 일어난 것은?", opts:["먹는[멍는]","물난리[물랄리]","앞마당[암마당]","밥물[밤물]"], a:1, exp:"'물난리'는 ㄴ이 ㄹ의 앞뒤에서 ㄹ로 바뀐 유음화. 나머지는 ㄱ·ㅂ이 비음 앞에서 비음으로 바뀐 비음화. 결과 소리가 유음(ㄹ)인지 비음(ㅇ·ㄴ·ㅁ)인지로 가른다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<보기>\n㉠ 음절의 끝소리 규칙: 받침이 ㄱ·ㄴ·ㄷ·ㄹ·ㅁ·ㅂ·ㅇ 중 하나로 바뀜(교체).\n㉡ 비음화: ㄱ·ㄷ·ㅂ이 ㄴ·ㅁ 앞에서 ㅇ·ㄴ·ㅁ으로 바뀜(교체).\n㉢ ㄴ 첨가: 합성어·파생어에서 앞말이 자음으로 끝나고 뒷말이 '이·야·여·요·유'로 시작하면 ㄴ이 덧남.\n\n[탐구 자료] ⓐ 옷맵시 ⓑ 늦여름 ⓒ 밥맛 ⓓ 담요", q:"<보기>를 바탕으로 ⓐ~ⓓ를 탐구한 내용으로 옳은 것은?", opts:["ⓐ에는 ㉢이 적용되어 음운의 수가 늘어난다.","ⓑ에는 ㉠·㉢·㉡이 모두 적용되어 음운의 수가 하나 늘어난다.","ⓒ에는 ㉢이 적용되어 [밤냗]으로 발음된다.","ⓓ에는 ㉡이 적용되어 [담뇨]로 발음된다."], a:1, exp:"ⓑ늦여름: ㅈ→ㄷ(㉠)→ㄴ 첨가(㉢)→ㄷ→ㄴ(㉡)=[는녀름], 첨가로 +1. ⓐ[온맵씨]는 ㉠·㉡·된소리되기이며 첨가 없음. ⓒ[밤맏]은 ㉡·㉠. ⓓ[담뇨]는 ㉢(첨가)이지 비음화가 아니다.", why3:"'모두 적용'된 단어가 정답인 경우가 많다 — 세 조건을 단어마다 순서대로 대입한다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"계산", q:"'홑이불'의 표준 발음을 쓰고, 적용된 음운 변동을 순서대로 유형과 함께 서술한 뒤 변동 전후의 음운 수를 비교하시오.", model:"표준 발음은 [혼니불]이다. 먼저 음절의 끝소리 규칙으로 ㅌ이 ㄷ으로 바뀌고(교체), '이불' 앞에 ㄴ이 첨가되며(첨가), 이어 ㄷ이 ㄴ 앞에서 ㄴ으로 바뀐다(비음화·교체). 변동 전 음운은 ㅎ·ㅗ·ㅌ·ㅣ·ㅂ·ㅜ·ㄹ 7개, 변동 후는 ㅎ·ㅗ·ㄴ·ㄴ·ㅣ·ㅂ·ㅜ·ㄹ 8개로 하나 늘었다.", rubric:[["발음 [혼니불]",2],["끝소리 규칙 → ㄴ 첨가 → 비음화 순서",3],["유형 표시(교체·첨가·교체)",2],["음운 수 7→8",2],["문장 완결",1]], exp:"한 단계만 쓰면 부분 점수. 음운 수는 표기 글자가 아니라 소리 기준으로 세어야 한다." }
 ],

 "kor-h2-hwaeon-word": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"밑줄 친 말의 품사가 나머지와 **다른** 것은?", opts:["너**만큼** 열심히 하는 사람은 없다.","노력한 **만큼** 결과가 나왔다.","그는 집**만큼** 편한 곳이 없다고 했다.","나도 너**만큼** 할 수 있다."], a:1, exp:"②는 관형어 '노력한' 뒤에 쓰여 의존 명사. 나머지는 체언 뒤에 붙은 조사. 품사 통용은 앞말이 체언인지 관형어인지로 판단한다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 중 파생어이면서 어근과 **품사가 달라진** 단어는?", opts:["덮개","맨손","산길","새파랗다"], a:0, exp:"'덮개'는 동사 어근 '덮-'에 접미사 '-개'가 붙어 명사가 되었다. '맨손·새파랗다'는 접두사가 붙어 품사가 유지된 파생어, '산길'은 합성어.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<보기> 단어는 어근과 접사로 분석한다. 어근이 둘 이상이면 합성어, 접사가 결합하면 파생어이며, 합성어의 어근 자리에 이미 파생어가 올 수도 있다.\n\n<학습 활동> 다음 단어의 짜임을 분석해 보자.\n㉠ 헛웃음 ㉡ 책꽂이 ㉢ 손발 ㉣ 되새김질", q:"<보기>를 바탕으로 학습 활동을 수행한 결과로 옳은 것만 고른 것은?\nㄱ. ㉠은 접두사 '헛-'이 파생어 '웃음'에 결합한 파생어이다.\nㄴ. ㉡은 어근 '책'과 파생어 '꽂이'가 결합했으므로 합성어이다.\nㄷ. ㉢은 두 어근이 대등하게 결합한 합성어이다.\nㄹ. ㉣은 어근이 둘이므로 합성어이다.", opts:["ㄱ, ㄴ","ㄷ, ㄹ","ㄱ, ㄴ, ㄷ","ㄱ, ㄷ, ㄹ"], a:2, exp:"㉠헛-+(웃-+-음), ㉡책+(꽂-+-이)로 어근이 둘이므로 합성어, ㉢손+발 합성어. ㉣은 되-+(새기-+-ㅁ)+-질로 어근은 '새기-' 하나뿐이고 접사만 셋이므로 파생어.", why3:"마지막에 결합한 요소가 접사인지 어근인지로 전체 짜임이 정해진다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"'나는 친구가 건넨 책이 무척 재미있다고 생각했다.'의 문장 성분을 분석하시오. 서술어와 그 주어를 짝지어 절의 수를 밝히고, 안긴문장을 모두 찾아 종류와 문장 속 역할을 쓰며, 생략된 성분이 있으면 복원하시오.", model:"서술어는 '건넨(주어: 친구가)·재미있다(주어: 책이)·생각했다(주어: 나는)' 셋이므로 절이 세 개인 겹문장이다. '친구가 건넨'은 '책'을 꾸미는 관형절로 '친구가 (책을) 건넸다'에서 목적어가 생략되었다. '친구가 건넨 책이 무척 재미있다고'는 '-고'가 붙은 인용절로 '생각했다'의 내용이 되며, 그 안에 관형절이 다시 안겨 있다.", rubric:[["서술어–주어 짝 3개",3],["관형절 + 역할(관형어)",2],["인용절 + 역할",2],["생략 성분 '책을' 복원",2],["문장 완결",1]], exp:"'책이'를 전체 문장의 주어로 쓰면 감점 — 서술어 '재미있다'와 호응하는 안긴문장의 주어다." }
 ],

 "kor-h2-hwaeon-speech": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 글에서 ㉠과 ㉡의 문제를 바르게 짝지은 것은?\n\n우리 학교는 분리수거함을 늘려야 한다. ㉠ 그러나 쓰레기 배출량이 작년보다 20% 늘었기 때문이다. ㉡ 우리 학교 급식은 맛있기로 유명하다. 분리수거함이 늘면 재활용률도 오를 것이다.", opts:["㉠ 통일성, ㉡ 응집성","㉠ 응집성, ㉡ 통일성","㉠·㉡ 모두 응집성","㉠·㉡ 모두 통일성"], a:1, exp:"㉠은 근거를 잇는 자리에 반대 접속어 '그러나'를 써 문장 연결(응집성)이 깨졌고, ㉡은 주제와 무관해 통일성을 해친다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"실험 보고서의 문장 \"실험 중 측정 장비가 파손되었다.\"에 쓰인 문법 요소와 그 효과로 가장 적절한 것은?", opts:["사동 표현으로 행위를 강조한다.","피동 표현으로 행위 주체를 드러내지 않아 책임이 분산된다.","추측 표현으로 확신의 정도를 낮춘다.","직접 인용으로 객관성을 높인다."], a:1, exp:"'파손되었다'는 피동으로, 누가 파손했는지가 드러나지 않는다. 추측·사동·인용 표현은 쓰이지 않았다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 발표>\n안녕하세요. 오늘은 교내 분리배출 실태를 말씀드리겠습니다. (그래프를 가리키며) ㉠보시는 것처럼 플라스틱 분리배출률이 지난해보다 12%p 떨어졌습니다. 원인은 ㉡분리수거함 안내문이 잘 읽히지 않기 때문인 것으로 보입니다. ㉢여러분도 안내문을 보고 어디에 버릴지 망설인 적이 있으시죠? 그래서 저희는 그림 안내문을 제안합니다. ㉣질문이 있으시면 말씀해 주세요.", q:"발표에 대한 설명으로 적절하지 **않은** 것은?", opts:["㉠은 그래프의 핵심 수치를 말로 짚어 자료가 보여 주는 바를 분명히 했다.","㉡은 피동 표현과 추측 표현을 써서 원인을 단정하지 않는 태도를 드러낸다.","㉢은 청중의 경험을 환기하여 공감을 끌어내는 질문이다.","㉣은 반대 신문으로 청중 논증의 허점을 검증하려는 발화이다."], a:3, exp:"㉣은 질의응답을 여는 발표 마무리 발화이지 토론의 반대 신문이 아니다. ㉡'읽히지'(피동)+'것으로 보입니다'(추측)로 확신 정도를 낮춘 것은 맞다.", why3:"담화 유형(발표)을 먼저 고정하면 '반대 신문' 같은 다른 유형의 용어가 든 선지가 걸러진다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"토론 논제 '교복을 자율화해야 한다'의 찬성 측 입론이다. \"한 대학 연구에 따르면 자율 복장 학교 학생의 만족도가 높습니다. 또 교복비는 가계에 큰 부담입니다.\" 반대 측이 반대 신문에서 할 질문을 두 개 만들고, 각 질문이 상대 논증의 무엇(신뢰성·타당성·공정성 중)을 검증하는지 서술하시오.", model:"질문 ①: '한 대학 연구'는 어느 기관이 언제 몇 개 학교를 조사한 것입니까? — 근거 출처의 신뢰성을 검증한다. 질문 ②: 만족도가 높다는 것이 곧 교복 자율화를 해야 할 이유가 됩니까? 학습 분위기나 비용 차이는 비교했습니까? — 근거가 주장을 실제로 뒷받침하는지, 즉 타당성(관련성·충분성)을 검증한다.", rubric:[["질문 ① 의문문 형식·출처 확인",3],["질문 ① 검증 대상: 신뢰성",1],["질문 ② 의문문 형식·근거–주장 연결 확인",3],["질문 ② 검증 대상: 타당성",1],["반박이 아닌 질문으로 작성",1],["문장 완결",1]], exp:"'그 주장은 틀렸다'처럼 반박문을 쓰면 질문 항목 0점. 반대 신문은 질문으로 상대 논증을 드러내는 단계다." }
 ],

 "kor-h2-dokjak-fact": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"\"심해 생물은 대체로 성장이 느리다. 먹이가 적고 수온이 낮아 물질대사가 더디기 때문이다. 다만 열수 분출구 주변처럼 먹이가 풍부한 곳에서는 비교적 빠르게 자라는 종도 있다.\" 이 글의 내용과 일치하는 것은?", opts:["모든 심해 생물은 성장이 느리다.","심해 생물의 느린 성장은 먹이 부족과 낮은 수온과 관련이 있다.","열수 분출구 주변의 생물은 수온이 낮아 성장이 느리다.","심해 생물은 수온이 높을수록 성장이 느리다."], a:1, exp:"②는 둘째 문장을 말만 바꾼 것. ①'모든'은 '대체로'와 '다만 ~종도 있다'에 어긋남, ③④는 지문과 관계가 뒤집히거나 근거 없음.", err:"추론" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"\"이 제도는 지역 간 격차를 **메우는** 데 목적이 있다.\"의 '메우는'과 같은 의미로 쓰인 것은?", opts:["구덩이를 흙으로 메우다","부족한 인원을 새 직원으로 메우다","빈 시간을 독서로 메우다","빈 그릇을 국으로 메우다"], a:1, exp:"문맥상 '격차를 메우다'는 '모자라는 것을 채워 없애다'. ②'부족한 인원을 메우다'가 같은 뜻. ①④는 빈 공간을 물질로 채움, ③은 시간을 채움.", err:"어휘" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 지문> 도서관 자료는 등급 A·B·C로 나뉜다. A는 누구나 대출할 수 있다. B는 연체 기록이 없는 회원만 대출할 수 있다. C는 대출이 불가능하고 열람만 허용된다. 단, 연체 기록이 있어도 연체료를 모두 납부하면 기록은 소멸한 것으로 본다. 한 회원이 동시에 빌릴 수 있는 자료는 세 권이며, C 등급 열람은 이 수에 포함되지 않는다.\n\n<보기> 수진은 지난달 연체한 뒤 연체료를 모두 냈다. 현재 A 자료 두 권을 빌린 상태다.", q:"윗글을 바탕으로 <보기>의 수진에 대해 추론한 내용으로 가장 적절한 것은?", opts:["수진은 B 자료를 한 권 더 빌릴 수 있다.","수진은 연체 기록이 있으므로 B 자료를 빌릴 수 없다.","수진은 C 자료를 빌려 세 권을 채울 수 있다.","수진이 C 자료를 열람하면 더 이상 대출할 수 없다."], a:0, exp:"연체료를 냈으므로 기록 소멸→B 대출 가능, 현재 두 권이므로 한 권 더 가능(①). ②는 '단' 조항을 놓침, ③C는 대출 불가, ④열람은 대출 수에 포함되지 않는다.", why3:"규칙 추론은 '단·다만' 뒤의 예외 조항부터 <보기>에 대입한다.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"\"스마트폰 사용 시간을 줄이면 수면의 질이 좋아진다. 따라서 학교는 밤 10시 이후 학습 앱의 알림을 끄도록 권장해야 한다.\" 이 논증에서 글쓴이가 드러내지 않고 전제하고 있는 것을 두 가지 추론하여 쓰고, 각 전제가 없으면 결론이 성립하지 않는 이유를 서술하시오.", model:"첫째, 학습 앱의 알림이 학생의 스마트폰 사용 시간을 늘린다는 전제가 숨어 있다. 이것이 없으면 알림을 꺼도 사용 시간이 줄지 않아 결론과 근거가 이어지지 않는다. 둘째, 학생의 수면의 질은 학교가 개입해 개선할 가치가 있는 문제라는 전제가 있다. 이것이 없으면 수면이 좋아진다는 사실이 '학교가 권장해야 한다'는 당위로 이어지지 않는다.", rubric:[["전제 ① 알림–사용 시간 연결",3],["전제 ① 없을 때의 단절 설명",2],["전제 ② 학교의 개입 정당성",2],["전제 ② 없을 때의 단절 설명",2],["문장 완결",1]], exp:"지문에 이미 쓰인 문장을 전제로 쓰면 0점. 근거와 결론 사이의 '빠진 다리'를 찾아야 한다." }
 ],

 "kor-h2-dokjak-critical": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"\"전동 킥보드는 위험하다. 지난주 우리 동네에서 킥보드 사고가 두 건 났고, 내 친구도 킥보드를 타다 넘어졌다. 킥보드 이용자 수나 자동차 사고 건수는 굳이 비교할 필요가 없다.\" 이 글에 대한 비판으로 가장 적절한 것은?", opts:["사실과 의견을 구분하지 않았다.","주장에 유리한 사례만 선택하고 비교 자료를 배제해 관점이 편향되었다.","전문 용어를 지나치게 많이 썼다.","결론을 제시하지 않았다."], a:1, exp:"가까운 사례 몇 개만 고르고 비교에 필요한 자료(이용자 수·다른 사고 건수)를 의도적으로 뺐으므로 자료 선택의 편향. 결론은 첫 문장에 있다.", err:"추론" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"'방관자 효과'란 주변에 사람이 많을수록 개인이 도움 행동을 하지 않게 되는 현상이다. 이 개념이 적용된 사례는?", opts:["혼자 길을 가던 민수가 쓰러진 사람을 보고 바로 신고했다.","붐비는 역에서 쓰러진 사람을 수십 명이 보았지만 누구도 신고하지 않았다.","두 명이 함께 있다가 쓰러진 사람을 보고 각자 신고했다.","응급 구조사가 현장에서 환자를 치료했다."], a:1, exp:"'사람이 많을수록'과 '도움 행동을 하지 않음' 두 조건을 모두 만족하는 것은 ②뿐. ①은 혼자, ③은 도왔고, ④는 직업적 행동.", err:"추론" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 글 두 편>\n(가) 도시의 자율 주행 버스는 운전자 부족 문제를 해결하고 사고를 줄인다. 교통사고의 90% 이상이 사람의 실수에서 비롯되기 때문이다.\n(나) 자율 주행 버스는 사고가 났을 때 책임 소재가 불분명하고, 돌발 상황 판단은 아직 사람보다 느리다. 기술 도입보다 제도 정비와 검증이 먼저다.\n\n<학습 활동> (가)·(나)의 논의를 '현상에 대한 진단 – 해법 – 숨은 전제'의 세 항목으로 정리해 보자.", q:"학습 활동을 수행한 결과로 가장 적절한 것은?", opts:["(가)는 사고 원인을 사람의 실수로 진단하고, 기술이 사람을 대체하면 문제가 해결된다는 전제를 깔고 있다.","(나)는 사고 원인 진단에서 (가)와 완전히 일치한다.","(나)의 해법은 자율 주행 기술의 도입을 영구히 금지하는 것이다.","(가)와 (나)는 모두 자율 주행 기술이 이미 충분히 검증되었다고 전제한다."], a:0, exp:"(가)의 근거 '사람의 실수'와 해법 '자율 주행' 사이에는 '기술이 실수를 대체·제거한다'는 전제가 있다. (나)는 판단 속도·책임 문제를 진단하고 '제도·검증이 먼저'를 해법으로 삼으며 기술이 미검증이라 본다.", why3:"'완전히·영구히·모두' 같은 범위 확장 어휘가 든 선지는 (가)(나) 비교에서 대개 오답.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"위 (나)의 관점에서 (가)의 논증을 비판하는 글을 쓰시오. (가)의 근거가 지닌 한계를 (나)의 내용을 활용해 지적하고, (가)가 보완해야 할 점을 제시하시오.", model:"(가)는 교통사고의 90% 이상이 사람의 실수라는 통계를 근거로 자율 주행 버스가 사고를 줄인다고 주장한다. 그러나 (나)가 지적하듯 자율 주행은 돌발 상황 판단이 아직 사람보다 느리므로, 사람의 실수가 줄어도 기계의 판단 오류라는 새로운 사고 원인이 생길 수 있다. 또 사고 시 책임 소재가 불분명한 제도적 공백도 (가)는 다루지 않았다. 따라서 (가)는 자율 주행 버스의 실제 사고율 자료와 책임 제도에 관한 논의를 보완해야 한다.", rubric:[["(가)의 근거·주장 정리",2],["(나)를 활용한 한계 지적 ① 판단 속도",2],["(나)를 활용한 한계 지적 ② 책임 소재",2],["보완할 점 제시",3],["문장 완결",1]], exp:"(나)의 내용을 쓰지 않고 자기 생각만으로 비판하면 활용 항목 0점. '(나)의 관점에서'라는 조건을 지켜야 한다." }
 ],

 "kor-h2-dokjak-writing": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"고쳐쓰기의 수준이 바르게 짝지어진 것은?", opts:["주제와 무관한 문단을 삭제했다. — 단어 수준","'비록 ~하지만'의 호응이 어긋난 문장을 고쳤다. — 문장 수준","'너무 좋다'를 '매우 좋다'로 바꾸었다. — 글 수준","중심 문장이 없는 문단에 중심 문장을 넣었다. — 단어 수준"], a:1, exp:"문장 호응은 문장 수준. 문단 삭제·독자 적합성은 글 수준, 어휘 교체는 단어 수준, 중심 문장 보강은 문단 수준.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"'학교 주변 횡단보도 안전' 글의 개요에서 <자료>를 활용하기에 가장 적절한 위치는?\n\n<자료> 최근 3년간 등하교 시간 학교 앞 횡단보도 사고가 매년 늘어 올해 12건에 이르렀다.", opts:["서론: 문제의 심각성 제시","본론 1: 해결 방안(신호등 설치) 제안","본론 2: 해결 방안의 기대 효과","결론: 독자에게 실천 당부"], a:0, exp:"자료는 사고가 늘고 있다는 '현황'이므로 문제의 심각성을 보이는 서론에 알맞다. 같은 통계도 용도(심각성/효과)에 따라 자리가 달라진다.", err:"추론" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<글쓰기 계획> 주제: 학교 옥상 정원 조성을 제안한다. 독자: 교장 선생님과 학생회.\n<자료>\n(ㄱ) 통계: 옥상 정원이 있는 학교는 여름철 최상층 교실 온도가 평균 2.3℃ 낮음\n(ㄴ) 설문: 우리 학교 학생 68%가 쉬는 시간에 갈 만한 야외 공간이 없다고 답함\n(ㄷ) 사례: 인근 학교가 학생 동아리 주도로 옥상 정원을 만들어 관리 비용을 줄임\n<개요> Ⅰ 문제 제기 – Ⅱ 기대 효과 – Ⅲ 실행 방안 – Ⅳ 당부", q:"자료 활용 방안으로 적절하지 **않은** 것은?", opts:["(ㄴ)은 Ⅰ에서 야외 공간 부족이라는 문제의 실태를 보여 주는 근거로 활용한다.","(ㄱ)은 Ⅱ에서 정원의 냉방 효과를 수치로 뒷받침하는 데 활용한다.","(ㄷ)은 Ⅲ에서 학생 주도 운영으로 비용 문제를 해결하는 방안의 근거로 활용한다.","(ㄱ)은 Ⅳ에서 독자의 감정에 호소하는 데 활용한다."], a:3, exp:"(ㄱ)은 객관적 수치로 효과를 보이는 자료이지 감정 호소용이 아니며, 당부(Ⅳ)에 쓸 자료도 아니다. 나머지는 자료의 내용과 개요의 용도가 맞게 연결된다.", why3:"자료마다 '핵심 사실 한 줄'을 적고 개요의 어느 칸이 그 사실을 필요로 하는지 연결한다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"실수", q:"다음 초고에서 고쳐야 할 문장 두 개를 찾아 각각 고쳐 쓰고, 어떤 수준(글·문단·문장·단어)의 어떤 문제였는지 이유를 서술하시오.\n㉠ 내가 이 글을 쓰는 이유는 급식 잔반을 줄이자고 제안하고 싶다. ㉡ 우리 학교 잔반은 하루 평균 60kg에 이른다. ㉢ 급식실 조리사 선생님들은 늘 친절하시다. ㉣ 잔반을 줄이면 급식의 질을 높이는 데 예산을 쓸 수 있다.", model:"㉠은 주어 '이유는'과 서술어 '싶다'가 호응하지 않는 문장 수준의 문제이므로 '내가 이 글을 쓰는 이유는 급식 잔반을 줄이자고 제안하기 위해서이다.'로 고친다. ㉢은 조리사의 친절이 잔반 줄이기라는 문단의 중심 내용과 관련이 없어 통일성을 해치는 문단 수준의 문제이므로 삭제한다.", rubric:[["㉠ 지목 + 호응 맞게 수정",3],["㉠ 이유: 문장 수준·주어–서술어 호응",2],["㉢ 지목 + 삭제",2],["㉢ 이유: 문단 수준·통일성",2],["문장 완결",1]], exp:"㉡·㉣을 고르면 0점. ㉠의 수정문에 '~기 위해서이다/~기 때문이다' 호응이 드러나야 한다." }
 ],

 "kor-h2-munhak-history": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"판소리계 소설의 특징으로 가장 적절한 것은?", opts:["서술자가 전혀 개입하지 않고 사건만 객관적으로 전달한다.","해학과 풍자가 두드러지고 서술자가 끼어들어 평하기도 하며 장면이 확장된다.","향찰로 표기되어 한글 창제 이후 기록되었다.","사물을 의인화하여 교훈을 전하는 짧은 이야기이다."], a:1, exp:"판소리계 소설은 구연에서 비롯되어 해학·풍자, 장면 확장, 편집자적 논평이 특징. ①은 현대 소설 관찰자 서술, ③은 향가, ④는 가전.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"문학과 역사의 상호 영향에 대한 설명으로 옳은 것은?", opts:["양란 이후 신분 질서가 흔들리면서 평민 화자의 사설시조와 서민 영웅이 나오는 소설이 늘었다.","작품은 시대를 반영할 뿐 시대의 인식을 바꾸지는 못한다.","조선 전기 사대부 시조는 주로 신분제를 비판했다.","고려 가요는 한글로 창작되어 바로 기록되었다."], a:0, exp:"전란 뒤 사회 변동이 새 갈래와 인물형을 낳았다. 작품은 신분제 비판처럼 인식을 바꾸기도 하고(②×), 전기 시조는 절의·자연을 노래했으며(③×), 고려 가요는 구전 뒤 한글로 기록되었다(④×).", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 고전풍 노래>\n(가) 산중에 벗이 없어 솔과 달을 벗 삼으니\n     바위 틈 흐르는 물이 거문고 소리로다\n     세상 시비 들릴세라 귀 씻고 앉았노라\n(나) 개미 한 마리 쌀 한 톨 물고 가다 장승에게 혼쭐나네\n     장승 왈 그 쌀이 관가 쌀이냐 묻자 개미 왈\n     내 땀으로 거둔 쌀도 관가 쌀이라 하시면 어느 쌀이 내 쌀이오 하더라\n\n<보기> 조선 전기 사대부 시조는 자연 속 삶의 만족을 노래했고, 양란 이후의 사설시조에는 평민의 삶과 현실 비판이 해학적으로 담겼다.", q:"<보기>를 참고하여 (가)와 (나)를 감상한 내용으로 적절하지 **않은** 것은?", opts:["(가)의 화자는 자연물을 벗과 악기로 여기며 자연 속 삶의 만족을 드러낸다.","(나)는 개미와 장승의 대화라는 우의적 설정으로 관의 수탈을 해학적으로 비판한다.","(가)의 '세상 시비'는 화자가 적극적으로 나서 바로잡으려는 대상이다.","<보기>로 보아 (나)는 (가)보다 뒤 시기의 작품으로 볼 수 있다."], a:2, exp:"'들릴세라 귀 씻고'는 세상일을 피하려는 태도이므로 '바로잡으려는'은 작품 사실과 어긋난다. (나)의 장형화·평민 화자·현실 비판은 사설시조의 특징이라 후기 작품으로 본다.", why3:"구절의 사실(피함/나섬)을 먼저 확정하고 <보기>를 입힌다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"위 (나)에 창작 당시의 시대 상황이 어떻게 반영되었는지 서술하시오. '시대 상황 규정 → 근거 구절 인용 → 반영 양상(표현 방식 포함)'의 세 단계를 갖추시오.", model:"(나)가 지어진 조선 후기는 전란 뒤 관의 수탈이 심해지고 신분 질서가 흔들려 평민의 불만이 커지던 시기였다. '내 땀으로 거둔 쌀도 관가 쌀이라 하시면 어느 쌀이 내 쌀이오'라는 개미의 항변에는 제 노동의 결실조차 빼앗기는 백성의 처지가 담겨 있다. 작가는 이를 개미와 장승이라는 우의적 인물의 대화로 바꾸어, 직접 고발 대신 웃음을 섞은 해학과 풍자로 관의 횡포를 비판하는 사설시조의 방식을 보여 준다.", rubric:[["시대 상황 규정(후기·수탈·질서 동요)",3],["근거 구절 인용",2],["반영 양상(백성의 처지)",2],["표현 방식(우의·해학·풍자)",2],["문장 완결",1]], exp:"구절 인용 없이 '수탈을 비판한다'만 쓰면 2단계 0점. 세 단계가 '그래서' 로 이어져야 만점." }
 ],

 "kor-h2-munhak-modern": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 소설 대목의 서술상 특징으로 가장 적절한 것은?\n\n그 후 삼 년 동안 윤수는 세 번 직장을 옮겼고 두 번 이사했다. 어머니는 그때마다 짐을 쌌다. 그러던 어느 봄날 아침, 어머니가 말했다. \"이번엔 네가 싸라.\"", opts:["긴 시간을 요약적으로 제시한 뒤 특정 장면을 대화로 보여 준다.","처음부터 끝까지 장면을 대화로만 제시한다.","서술자가 인물의 속마음을 직접 설명한다.","사건을 역순행적으로 배열한다."], a:0, exp:"'삼 년 동안 ~ 옮겼고'는 요약적 제시, '어느 봄날 아침'부터는 대화로 보여 주는 장면 제시. 속마음 설명이나 시간 역전은 없다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"\"가장 시끄러운 고요가 그 방에 있었다.\"라는 시구의 표현법과 효과를 바르게 설명한 것은?", opts:["반어 — 겉으로는 칭찬하며 속으로는 비판한다.","역설 — 모순된 말을 통해 침묵 속의 긴장감을 강렬하게 드러낸다.","직유 — 두 대상을 '~처럼'으로 연결해 생생하게 그린다.","의인 — 방에 사람의 성격을 부여해 친근감을 준다."], a:1, exp:"'시끄러운 고요'는 문장 자체가 모순인 역설로, 소리 없는 긴장을 강조한다. 기법 이름과 효과를 한 세트로 확인한다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<이론> 시에서 화자가 대상과 거리를 두고 담담하게 말하면 정서가 절제되어 오히려 여운이 커진다. 반면 감탄형·명령형 어조는 정서를 직접 분출한다.\n\n<자작 시>\n어머니는 늘 식은 밥을 드셨다\n우리가 먹고 남긴 그릇을 모아\n말없이 부엌 구석에 앉아서\n나는 그때 그 등을 보지 않았다\n이제 와 밥이 식기를 기다린다", q:"<이론>을 바탕으로 <자작 시>를 감상한 내용으로 적절하지 **않은** 것은?", opts:["화자는 과거의 어머니를 담담한 어조로 서술하여 정서를 절제하고 있다.","'그 등을 보지 않았다'는 과거의 무심함을 고백하며 뒤늦은 후회를 드러낸다.","마지막 행에서 화자는 어머니의 행위를 따라 하며 뒤늦은 이해를 보여 준다.","감탄형 어조를 반복하여 그리움을 직접 분출하고 있다."], a:3, exp:"시 전체가 평서형의 담담한 진술이며 감탄형은 없다. 절제된 어조가 '밥이 식기를 기다린다'는 행위의 반복에 여운을 더한다는 것이 <이론>과 맞는 감상.", why3:"이론 지문의 두 대립 개념(절제/분출) 중 작품이 어느 쪽인지 먼저 정하고 반대쪽 선지를 지운다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"다음 시에서 반복되는 구절을 찾아 그대로 쓰고, 그 반복이 주제를 형상화하는 데 주는 효과를 마지막 행과 관련지어 서술하시오.\n\n비가 온다\n우산도 없이 비가 온다\n너 없는 거리에 비가 온다\n나는 젖지 않는다", model:"반복되는 구절은 '비가 온다'이다. 세 번의 반복은 운율을 만들면서 '우산도 없이', '너 없는 거리에'라는 수식이 덧붙을수록 화자의 쓸쓸한 상황을 점점 쌓아 올린다. 그런데 마지막 행 '나는 젖지 않는다'는 반복의 흐름을 끊으며, 비에 젖지 않을 만큼 이미 슬픔에 무감각해진 화자의 상태를 역설적으로 드러내 상실감이라는 주제를 강조한다.", rubric:[["반복 구절 '비가 온다' 정확 인용",2],["효과 ① 운율·상황의 누적(점층)",3],["효과 ② 마지막 행의 전환·대비",3],["주제(상실·무감각)와 연결",1],["문장 완결",1]], exp:"'강조한다'만 쓰면 효과 항목 1점. 무엇이 어떻게 강조되는지와 마지막 행의 전환을 함께 써야 만점." }
 ],

 "kor-h2-munhak-reception": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 <보기>의 비평 관점은?\n\n<보기> 이 시인은 오랜 병상 생활 끝에 이 작품을 썼다. '닫힌 창'은 병실에서 바깥을 바라보던 시인 자신의 체험이 투영된 것이다.", opts:["내재적 관점","표현론적 관점","반영론적 관점","효용론적 관점"], a:1, exp:"작가 개인의 삶·체험을 근거로 작품을 해석하므로 표현론. 시대·사회를 끌어오면 반영론, 독자에게 주는 효과를 보면 효용론.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"전지적 작가 시점의 소설을 1인칭 관찰자 시점으로 재구성할 때 생기는 변화로 가장 적절한 것은?", opts:["주인공의 속마음을 서술자가 더 자세히 설명할 수 있게 된다.","서술자 '나'가 본 것만 전할 수 있어 주인공의 내면은 추측과 궁금증의 대상이 된다.","작품의 주제가 반드시 바뀐다.","사건의 순서를 반드시 바꾸어야 한다."], a:1, exp:"관찰자 '나'는 다른 인물의 내면에 접근할 수 없어 독자와 주인공 사이에 거리가 생긴다. 재구성은 형식을 바꾸되 주제·핵심 사건은 유지하는 것이 원칙.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 시>\n공장 굴뚝 아래 작은 텃밭\n아버지는 퇴근길마다 상추를 땄다\n연기 냄새 밴 잎을 씻고 또 씻으며\n그래도 우리 밭이라고 웃으셨다\n\n<학습 활동> 이 시를 ㉠ 반영론적 관점과 ㉡ 내재적 관점에서 각각 감상해 보자.", q:"학습 활동을 수행한 결과로 옳은 것만 고른 것은?\nㄱ. ㉠: '공장 굴뚝'과 '연기 냄새'를 산업화 시대 노동자 가정의 생활 조건과 연결한다.\nㄴ. ㉡: '씻고 또 씻으며'의 반복이 아버지의 애씀을 강조한다고 본다.\nㄷ. ㉠: 시인의 아버지가 실제 공장 노동자였다는 전기적 사실을 근거로 삼는다.\nㄹ. ㉡: '그래도'를 기점으로 어조가 전환되어 긍정적 태도가 드러난다고 본다.", opts:["ㄱ, ㄴ","ㄷ, ㄹ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ"], a:2, exp:"ㄱ은 시대·사회 현실과 연결한 반영론, ㄴ·ㄹ은 작품 내부의 반복·어조만으로 읽은 내재적 감상. ㄷ은 작가의 생애를 근거로 하므로 표현론이지 반영론이 아니다.", why3:"<보기>·활동의 주어가 '당시 사회'면 반영론, '작가'면 표현론 — 근거의 출처로 관점을 가른다.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"위 <자작 시>(공장 굴뚝 아래)에 대해 효용론적 관점에서 짧은 비평문을 쓰시오. 관점을 밝히고, 근거가 되는 구절을 둘 이상 인용하며, 이 시가 독자에게 주는 의미·가치를 평가하시오.", model:"효용론적 관점에서 이 시는 독자에게 고된 현실 속에서도 자기 삶을 긍정하는 태도를 일깨운다. '연기 냄새 밴 잎을 씻고 또 씻으며'는 열악한 환경에서도 가족을 위해 애쓰는 아버지의 모습으로 독자에게 부모의 노고를 돌아보게 하고, '그래도 우리 밭이라고 웃으셨다'는 작은 것을 소중히 여기는 마음을 전해 독자가 자신의 일상을 긍정하도록 이끈다. 따라서 이 시는 위로와 성찰의 가치를 지닌다.", rubric:[["효용론 관점 명시(독자에게 주는 효과)",2],["구절 인용 ① + 독자 효과",3],["구절 인용 ② + 독자 효과",3],["가치 평가 문장",1],["문장 완결",1]], exp:"시대 배경이나 작가 이야기를 근거로 쓰면 관점이 어긋나 감점. '독자에게 ~하게 한다'는 서술이 있어야 효용론이다." }
 ]
});

(window.DATA.problemsAdd = window.DATA.problemsAdd || []).push({
 "kor-h2-hwaeon-attitude": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 중 화자의 판단이 가장 조심스럽게 드러난 문장은?", opts:["이 방법이 옳다.", "이 방법이 옳음을 확신한다.", "이 방법은 반드시 옳다.", "이 방법이 옳은 것 같습니다."], a:3, exp:"'~ㄴ 것 같다'는 단정을 피하고 조심스럽게 판단함을 나타낸다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"\"약속을 깜빡 잊어 버렸어요.\"에서 '-어 버리다'가 더하는 뜻으로 알맞은 것은?", opts:["아쉬움이나 후회를 드러낸다","행위의 주체를 높인다","미래의 일을 추측한다","상대에게 명령한다"], a:0, exp:"보조 용언 '-어 버리다'는 일이 끝났음과 함께 아쉬움이나 후련함을 드러낸다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 담화> 학생회 회의\n\n회장: 축제 예산이 부족합니다. ㉠부스 수를 줄여야 하지 않을까요?\n총무: ㉡예산안이 늦게 제출되었습니다. 그래서 지원금이 줄었습니다.\n회장: ㉢제가 제출 일정을 미리 챙기지 못했습니다.\n서기: ㉣회의 내용은 제가 정리해 드리겠습니다.", q:"㉠~㉣에 대한 설명으로 적절하지 않은 것은?", opts:["㉠은 의문 형식으로 자기 의견을 완곡하게 제시한다.","㉡은 피동 표현으로 제출이 늦은 행위자를 드러내지 않는다.","㉢은 '못'을 써서 일정을 챙기지 않겠다는 의지를 나타낸다.","㉣은 '-어 드리다'로 상대를 위한 행위임을 드러낸다."], a:2, exp:"㉢의 '못'은 의지가 아니라 능력·상황 때문에 하지 못했음을 나타내며, 행위자를 밝혀 책임을 인정한다.", why3:"형태를 찾은 뒤 맥락 속 기능까지 확인하면 ③의 '의지'가 틀렸음이 보인다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"개념", q:"\"회의 시간이 변경되었습니다.\"와 \"제가 회의 시간을 변경했습니다.\"를 비교하여, 화자의 책임이 어떻게 달리 드러나는지 문법 요소를 근거로 서술하시오.", model:"앞 문장은 피동 표현을 써서 변경한 사람을 드러내지 않으므로 책임이 흐려진다. 뒤 문장은 능동 표현과 주어 '제가'를 써서 화자가 변경했음을 밝히므로 책임을 분명히 드러낸다.", rubric:[["앞 문장의 피동 표현 지적",3],["행위자 감춤과 책임 연결",3],["뒤 문장의 능동·주어 지적",2],["문장 완결",2]], exp:"문법 요소의 이름과 태도 효과를 함께 써야 한다." }
 ],
 "kor-h2-hwaeon-discuss": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"토의에서 사회자의 역할로 가장 알맞은 것은?", opts:["찬성 측의 승리를 선언한다","발언을 정리하고 쟁점을 좁힌다","자기 의견만 계속 제시한다","자료 제시를 금지한다"], a:1, exp:"사회자는 논의가 흐트러지지 않게 정리하고 다음 논점으로 이끈다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"통학로 안전 문제를 다루는 토의에서 '원인'을 분석하는 데 가장 직접 쓰이는 자료는?", opts:["학교 축제 일정", "학생회 임원 명단", "사고가 잦은 지점과 시간대를 정리한 표", "다른 학교의 교가"], a:2, exp:"사고 지점과 시간대 자료는 문제가 언제 어디서 왜 생기는지 분석하는 데 쓰인다.", err:"자료" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 자료> 학교 도서관 이용 활성화 토의\n\n자료 1(설문): 이용하지 않는 이유 — 개방 시간이 맞지 않음 52%, 읽을 책이 없음 23%, 공간이 불편함 15%, 기타 10%\n자료 2(운영 현황): 개방 시간 08:00~16:30, 하교 시간 16:40\n자료 3(사서 면담): 방과 후 1시간 연장은 도서부 학생이 도우면 가능하다. 신규 도서 구입 예산은 올해 남아 있지 않다.", q:"자료를 종합해 구성한 대안으로 가장 적절한 것은?", opts:["올해 예산으로 신규 도서를 대량 구입한다.","도서부의 도움을 받아 하교 뒤 1시간 더 개방한다.","개방 시간을 그대로 두고 공간만 넓힌다.","기타 응답을 가장 큰 원인으로 보고 추가 대책을 미룬다."], a:1, exp:"가장 큰 이유(개방 시간)와 하교 시간 불일치를 해결하고, 사서가 밝힌 실행 조건도 만족한다. ①은 예산 조건에 어긋난다.", why3:"원인 자료와 조건 자료를 모두 만족하는 선지만 남긴다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"<자작 상황> 급식 줄이 길어 점심시간이 부족하다는 문제를 해결하려고 한다. 학년별 시간차 배식안과 배식구 증설안을 효과와 실현 가능성의 기준으로 비교하고, 더 적절한 대안을 근거와 함께 서술하시오. (단, 올해 시설 공사 예산은 없다.)", model:"두 안 모두 대기 시간을 줄이는 효과가 있지만, 배식구 증설은 공사 예산이 없어 올해 실현하기 어렵다. 시간차 배식은 시간표 조정만으로 시행할 수 있으므로 더 적절하다.", rubric:[["효과 기준으로 비교",3],["실현 가능성 기준으로 비교",3],["예산 조건 활용",2],["대안과 근거 제시",2]], exp:"기준을 명시하고 주어진 조건을 근거로 써야 한다." }
 ],
 "kor-h2-dokjak-set": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"통합 세트의 학생 초고를 읽는 방법으로 가장 알맞은 것은?", opts:["초고의 내용을 사실로 받아들인다", "(가)·(나)를 읽지 않고 초고만 읽는다", "초고의 맞춤법만 확인한다", "초고의 문장마다 어느 글에서 왔는지 확인한다"], a:3, exp:"초고는 평가 대상이므로 원문과 대조해 출처와 왜곡을 확인한다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"'작문 계획'을 묻는 문항에서 가장 먼저 확인할 내용은?", opts:["계획에 적힌 내용이 초고에 실제로 나타나는지","계획표의 글자 수","학생의 이름","글의 제목 글자 수"], a:0, exp:"계획과 초고를 하나씩 대응시켜 반영 여부를 확인한다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 글>\n(가) 도시의 녹지가 줄면 식물의 수분 증발이 감소하여 여름철 기온이 더 오를 수 있다.\n(나) 옥상 녹화는 건물 표면 온도를 낮추는 데 도움을 준다. 다만 초기 비용이 들고 건물이 무게를 견딜 수 있어야 한다.\n(다) 학생 초고: 녹지가 줄면 기온이 오를 수 있다. ㉠옥상 녹화는 건물 표면 온도를 낮춘다. ㉡옥상 녹화는 어느 건물에나 비용 부담 없이 적용할 수 있다. ㉢우리 학교도 안전 진단 뒤 시범 설치를 검토하면 좋겠다.", q:"(다)에 대한 평가로 가장 적절한 것은?", opts:["㉠은 (나)의 정보와 어긋난다.","㉡은 (나)가 밝힌 비용과 무게 조건을 무시해 왜곡했다.","㉢은 (가)에 그대로 제시된 정보이다.","첫 문장은 (나)의 정보를 옮긴 것이다."], a:1, exp:"(나)는 초기 비용과 하중 조건을 밝혔으므로 ㉡은 왜곡이다. ㉢은 학생의 제안이고, 첫 문장은 (가)의 정보이다.", why3:"초고 문장마다 가·나·생각을 표시하면 왜곡이 바로 드러난다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"<자작 초고> \"전자책은 종이책보다 환경에 좋다. 그러므로 종이책을 없애야 한다.\" <자작 자료> \"전자책의 환경 영향은 기기 생산과 사용 기간에 따라 달라진다.\" 자료를 활용해 초고의 문제점을 지적하고 한 문장으로 고쳐 쓰시오.", model:"초고는 전자책이 항상 환경에 좋다고 단정했지만, 자료에 따르면 환경 영향은 기기 생산과 사용 기간에 따라 달라진다. 고쳐 쓰면 '전자책의 환경 영향은 기기 생산과 사용 기간에 따라 달라지므로 조건을 따져 이용을 판단해야 한다.'이다.", rubric:[["단정의 문제 지적",3],["자료 내용 활용",3],["조건을 반영해 고쳐 씀",3],["문장 완결",1]], exp:"문제 지적과 고쳐쓰기를 모두 해야 한다." }
 ],
 "kor-h2-dokjak-fields": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 중 분야와 읽기 초점의 연결이 알맞지 않은 것은?", opts:["인문 — 입장과 비판의 관계","사회 — 제도가 적용되는 조건","과학 — 과정과 인과","예술 — 수치의 소수점 계산"], a:3, exp:"예술 분야는 개념과 관점, 작품을 보는 시각에 초점을 둔다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"과학·기술의 원리를 설명하는 글을 쓸 때 가장 알맞은 조직 방식은?", opts:["일기처럼 감정을 중심으로 쓴다", "찬성과 반대만 나열한다", "과정을 순서대로 쓰고 인과를 밝힌다", "인물의 대화로만 쓴다"], a:2, exp:"원리 설명은 정의, 과정, 인과 순서로 조직하면 독자가 이해하기 쉽다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 글> 어느 도서관은 연체 도서를 반납하면 연체료를 면제한다. 다만 면제는 한 해에 한 번만 가능하고, 분실 도서에는 적용하지 않는다.\n\n<자작 사례> A는 올해 처음 연체 도서를 반납했다. B는 올해 두 번째로 연체 도서를 반납했다. C는 대출한 책을 잃어버렸다.", q:"글을 사례에 적용한 것으로 적절한 것은?", opts:["A와 B 모두 연체료를 면제받는다.","A만 면제받고 B와 C는 면제받지 못한다.","C는 분실했으므로 항상 면제받는다.","B만 면제받는다."], a:1, exp:"한 해 한 번 조건에 따라 A만 해당한다. B는 횟수 조건에, C는 분실 예외에 걸린다.", why3:"사회·문화 지문은 조건과 예외를 표시한 뒤 사례를 하나씩 대입한다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"<자작 글> \"태양광 패널은 빛을 받아 전기를 만든다. 만들어진 직류 전기는 변환 장치를 거쳐 가정에서 쓰는 교류 전기로 바뀐다.\" 이 글을 입력–과정–출력 틀로 정리하고, 이 틀이 설명하는 글에 유용한 까닭을 쓰시오.", model:"입력은 빛, 과정은 패널의 전기 생산과 변환 장치의 교류 변환, 출력은 가정에서 쓰는 교류 전기이다. 이 틀은 원리를 순서대로 보여 주어 독자가 과정과 인과를 쉽게 이해하게 한다.", rubric:[["입력·과정·출력 구분",4],["내용을 정확히 정리",3],["유용한 까닭",2],["문장 완결",1]], exp:"세 칸을 정확히 채우고 까닭을 함께 써야 한다." }
 ],
 "kor-h2-munhak-community": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"작품 속 공동체의 문제를 읽는 순서로 가장 알맞은 것은?", opts:["작가 이름 → 출판 연도 → 글자 수", "표현법 이름 → 쪽수 → 작가 이름", "결말 → 제목 → 표지", "문제 → 인물의 대응 → 결과"], a:3, exp:"누가 어떤 문제를 겪고 어떻게 대응했으며 결과가 어떠한지 확인한다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"\"작품을 읽고 낯선 처지의 인물을 이해하면서 내 태도를 돌아보았다.\"에 나타난 문학의 역할은?", opts:["자아 성찰과 타자 이해","문법 규칙 암기","작가 연보 정리","맞춤법 교정"], a:0, exp:"문학은 타자를 이해하고 자신을 돌아보게 한다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 자료> 공동체의 규칙은 구성원 모두의 목소리를 듣고 고쳐 나갈 때 정당성을 얻는다.\n\n<자작 소설> 강변 마을의 어른들은 오래된 수문 규칙을 고집했다. 물이 넘쳐 아랫마을 논이 잠기자, 아랫마을 사람 순이는 회의에 나와 피해를 말했다. 처음에는 모두 외면했지만, 다음 회의에서 양쪽 대표가 번갈아 수문을 관리하기로 했다.", q:"자료의 관점으로 소설을 이해한 것으로 가장 적절한 것은?", opts:["어른들이 규칙을 고집한 것은 정당성을 얻는 과정이다.","순이의 발언은 규칙을 고치는 계기가 되어 구성원의 목소리를 반영하게 했다.","양쪽 대표의 번갈아 관리는 규칙을 없앤 것이다.","아랫마을의 피해는 공동체와 무관한 개인의 문제이다."], a:1, exp:"순이의 발언과 공동 관리 결정이 '목소리를 듣고 고쳐 나감'에 대응한다. ③은 규칙을 없앤 것이 아니라 고친 것이다.", why3:"관점·내용·연결 세 부분을 나눠 판단한다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"<자작 소설> \"골목의 가로등이 꺼지자 아이들은 저녁 심부름을 무서워했다. 이웃들은 서로 미루다가, 결국 집집마다 대문 등을 켜 두기로 했다.\" 이 작품에 나타난 공동체의 문제와 해결 방식을 쓰고, 오늘날의 비슷한 문제와 연결해 자신의 생각을 서술하시오.", model:"작품의 문제는 꺼진 가로등으로 골목이 위험해졌는데도 서로 책임을 미룬 것이고, 이웃들은 집집마다 대문 등을 켜는 협력으로 해결했다. 오늘날 공동 주택의 안전 문제도 서로 미루지 않고 작은 역할을 나눌 때 풀릴 수 있다고 생각한다.", rubric:[["문제 파악",3],["해결 방식 파악",3],["오늘날과 연결",2],["자신의 생각",2]], exp:"작품의 근거와 자신의 생각을 구별해 써야 한다." }
 ],
 "kor-h2-munhak-critique": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"평론을 작품에 적용한 선지를 판단하는 기준으로 가장 알맞은 것은?", opts:["평론과 작품 구절이 실제로 대응하는가","선지의 길이가 충분한가","평론가가 유명한가","작품이 교과서에 실렸는가"], a:0, exp:"평론의 개념이 그 구절의 내용과 맞아야 한다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"비판적 감상에 해당하는 것은?", opts:["주인공의 슬픔에 함께 눈물을 흘렸다", "인물의 이름을 외웠다", "작품의 뒷이야기를 새로 꾸몄다", "작품이 제시한 해결 방식이 공정한지 따져 보았다"], a:3, exp:"비판적 감상은 작품의 가치와 표현의 적절성을 따진다. ①은 공감적, ③은 창의적 감상이다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"<자작 평론> 이 시의 화자는 자연을 찬양하는 데 그치지 않는다. 시 후반부의 시선 이동은 자연에서 인간의 삶으로 관심이 옮겨 갔음을 보여 준다.\n\n<자작 시> 강물은 저녁빛을 싣고 흐르는데 / 물새는 제 그림자를 끌고 난다 / 다리 아래 늦은 장꾼이 / 젖은 짐을 말없이 고쳐 멘다", q:"평론을 바탕으로 시를 이해한 것으로 가장 적절한 것은?", opts:["첫 행과 둘째 행은 장꾼의 삶을 직접 묘사한다.","넷째 행은 자연을 찬양하는 표현이다.","셋째 행부터 시선이 자연에서 인간의 삶으로 옮겨 간다.","화자의 시선은 처음부터 끝까지 물새에 머문다."], a:2, exp:"앞 두 행은 강물과 물새, 뒤 두 행은 장꾼을 그려 평론의 '시선 이동'과 맞는다.", why3:"평론의 개념을 시의 구체적인 구절 위치와 대응시킨다.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", err:"추론", q:"<자작 평론> \"이 소설의 짧은 문장은 인물의 불안을 드러낸다.\" <자작 소설> \"그는 시계를 봤다. 다시 봤다. 전화는 오지 않았다. 손이 떨렸다.\" 평론의 해석에 동의하는지 밝히고, 작품의 구절을 근거로 내용과 형식을 연결해 서술하시오.", model:"동의한다. '봤다', '다시 봤다'처럼 끊어지는 짧은 문장이 초조하게 반복되는 행동을 보여 주고, '손이 떨렸다'는 내용과 결합해 인물의 불안을 강조한다.", rubric:[["입장 제시",2],["구절 근거 제시",3],["형식의 특징 설명",3],["내용과 형식의 연결",2]], exp:"구절을 인용하고 형식의 효과까지 연결해야 한다." }
 ]
});
